const top_sion = {
  champion: '사이온',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (Q)\'결정타\'로 이동 속도를 올려 달라붙고 침묵까지 걸어 (E)\'심판\'으로 이어가는 근접 교환이 강해요. 가렌이 다가올 때 (E)\'학살자의 포효\'로 방어력을 먼저 깎아 두면 평타 교환이 편해지지만, (Q)\'결정타\'를 쓰면 걸려 있던 둔화가 풀린다는 점은 기억하세요. 한 번 교환한 뒤에는 (P)\'인내심\' 회복이 돌아오기 전에 웨이브 앞에서 계속 압박하세요.', lv3: '(Q)\'결정타\' 침묵을 맞은 뒤에는 (W)\'영혼의 용광로\'를 켤 수 없으니 가렌이 붙기 전에 보호막을 미리 켜 두세요. 둔화는 가렌이 (Q)\'결정타\'를 쓴 뒤에 걸어야 풀리지 않으니 (E)\'학살자의 포효\'를 한 박자 늦게 쓰고 (Q)\'대량 학살 강타\' 충전으로 이어가세요. (W)\'용기\'가 켜진 동안은 강인함 때문에 기절이 짧아지니 그 순간의 교환은 피하세요.', lv6: '체력이 크게 깎인 채 가렌 옆에 남아 있으면 (R)\'데마시아의 정의\'로 처단당하니 한 번 크게 맞았다면 일찍 빠지세요. 가렌이 (W)\'용기\'를 먼저 써 버렸다면 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우고 (W)\'영혼의 용광로\' 재시전으로 마무리할 기회예요. 가렌은 (P)\'인내심\'으로 라인에서 회복이 빠르니 정글러가 오는 타이밍에 맞춰 한 번에 터뜨리세요.', item: '가렌은 물리 피해가 중심이라 태양불꽃 방패의 방어력과 체력으로 시작하고, 붙어 있는 동안 불사르기 피해를 계속 누적시키세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소가 (P)\'인내심\' 회복을 눌러 줘서 가렌과 오래 교환하기 쉬워요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 막타를 먼저 챙기며 견제하고, 붙으면 (P)\'불의 심판\'으로 불을 붙여요. (Q)\'혀어어어업상\'은 대상 지정이라 미니언 뒤에 숨어도 피할 수 없으니 맞더라도 웨이브 정리에 집중하세요. 갱플랭크가 막타를 치러 앞으로 나올 때 (E)\'학살자의 포효\'로 미니언을 밀어 뒤에 서 있는 갱플랭크의 방어력을 깎아 두세요.', lv3: '(W)\'괴혈병 치료\'는 둔화를 풀고 체력을 채우니 (E)\'학살자의 포효\' 둔화만으로 추격하려고 하지 마세요. 반면 기절이 걸린 동안은 (W)\'괴혈병 치료\'도 쓸 수 없으니 충전을 마친 (Q)\'대량 학살 강타\' 기절은 그대로 들어가요. 깔린 (E)\'화약통\'은 갱플랭크가 평타로 터뜨리면 주변에 둔화가 걸리니 통 바로 옆에서 서성이지 마세요.', lv6: '(R)\'포탄 세례\'는 넓은 지역에 피해와 둔화를 깔아 도망과 추격을 모두 어렵게 만드니 그 안에서는 싸우지 마세요. 갱플랭크가 (E)\'화약통\'과 (W)\'괴혈병 치료\'를 다 쓴 뒤에 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우면 한 번에 끝낼 수 있어요. 통을 미리 깔아 둔 쪽으로 들어가면 오히려 내가 둔화에 걸리니 돌진 방향을 통이 없는 쪽으로 틀어 주세요.', item: '갱플랭크는 물리 견제가 주력이라 태양불꽃 방패로 방어력을 챙기고 라인을 오래 버티세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. (Q)\'혀어어어업상\' 견제로 체력이 빠지면 귀환 후 순간이동으로 바로 복귀하고, (R)\'포탄 세례\'로 다른 라인을 돕는 갱플랭크에게 순간이동 합류로 맞대응할 수 있어요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하고 스킬을 쓸 때마다 (P)\'서비스 시간\'으로 체력을 되찾아서 초반 소모전이 질겨요. 술통이 터질 자리를 보고 비켜서면서 (E)\'학살자의 포효\'로 미니언을 밀어 뒤에 있는 그라가스의 방어력을 깎아 두세요. 술통에 맞아 느려졌다면 무리해서 붙지 말고 웨이브를 정리하며 체력을 지키세요.', lv3: '(E)\'몸통 박치기\'는 지정한 위치로 몸을 날려 부딪힌 적을 기절시키니 그라가스의 E가 남아 있을 때는 (Q)\'대량 학살 강타\'를 오래 충전하며 서 있지 마세요. (W)\'취중 분노\'로 받는 피해가 줄어드는 동안은 교환을 멈추고, 끝난 뒤에 (W)\'영혼의 용광로\' 보호막을 켜고 들어가세요. E를 뺀 그라가스는 붙어 오는 수단이 줄어드니 그때 기절을 노리세요.', lv6: '(R)\'술통 폭발\'에 맞으면 멀리 밀려나서 상대 정글러가 있는 쪽으로 몰릴 수 있으니 교전 위치를 항상 신경 쓰세요. 그라가스가 궁극기와 (E)\'몸통 박치기\'를 다 쓴 뒤라면 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우고 (W)\'영혼의 용광로\'를 터뜨리세요. (P)\'서비스 시간\' 회복 때문에 체력이 애매하게 남으면 끊기 어려우니 들어갈 때 끝낼 각을 보고 들어가세요.', item: '그라가스의 술통과 (W)\'취중 분노\'는 마법 피해 쪽이라 공허한 광휘로 마법 저항력과 체력을 함께 챙기세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'서비스 시간\' 회복을 깎아야 소모전에서 체력 차이가 벌어져요.' },
    '그웬': { lv1: '그웬은 (Q)\'싹둑싹둑!\'을 여러 번 맞히면 중앙에 맞은 적에게 고정 피해가 들어가고 (P)\'가위 난도질\'로 체력을 회복해서 근접 교환이 질겨요. 가위질 원뿔의 중앙을 피해 옆으로 비켜서면 고정 피해를 덜 받아요. 웨이브가 쌓이면 (E)\'학살자의 포효\'로 미니언을 밀어 뒤의 그웬에게 방어력 감소를 걸어 주세요.', lv3: '(W)\'신성한 안개\'는 대상 지정만 막아서 지정형이 아닌 (Q)\'대량 학살 강타\'와 (E)\'학살자의 포효\'는 안개 안에서도 그대로 맞아요. 그웬이 (E)\'돌격가위\'로 붙어 공격 속도와 사거리를 늘린 구간은 (W)\'영혼의 용광로\' 보호막으로 버티고, 효과가 끝난 뒤에 반격하세요. 그웬이 안개 안에 서 있어도 (W)\'영혼의 용광로\' 재시전은 주변 적에게 들어가니 붙은 채로 터뜨리세요.', lv6: '(R)\'바느질\'은 다시 쓸 때마다 바늘이 늘어 피해가 커지고 둔화도 걸리니 그웬이 궁극기를 던지는 직선 위에서는 비켜서세요. (P)\'가위 난도질\'은 대상 체력에 비례하는 마법 피해라서 체력을 쌓은 사이온도 오래 맞을수록 손해가 커지니 길게 끌지 말고 기절을 맞혀 짧게 끝내세요. (R)\'멈출 수 없는 맹공\' 돌진은 안개 안의 그웬에게도 그대로 부딪혀요.', item: '그웬의 피해는 거의 마법이라 공허한 광휘로 마법 저항력과 체력을 챙기고, 불사르기로 붙어 있는 동안 피해를 보태세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'가위 난도질\' 회복을 눌러야 그웬과 길게 맞붙을 수 있어요.' },
    '나르': { lv1: '나르는 작은 상태에서 (Q)\'부메랑 던지기\'로 둔화를 걸며 멀리서 견제하고 싸울수록 분노를 모아요. 부메랑이 나르에게 돌아오는 동안 거리를 좁히고, 나르가 빠지는 방향으로 (E)\'학살자의 포효\'를 맞혀 방어력을 깎아 두세요. 분노가 가득 차면 다음 스킬에서 메가 나르로 변신하니 분노가 차오르는 걸 보고 교환을 줄이세요.', lv3: '작은 나르가 (E)\'폴짝\'으로 뛰어들어 올 때 착지 지점에 (Q)\'대량 학살 강타\' 충전을 맞춰 두면 기절 각이 나와요. 분노가 가득 찬 나르는 메가 나르의 (W)\'쿵쾅\' 기절 범위가 있으니 그 근처에서는 거리를 벌리세요. 나르의 (W)\'슝슝\'이 이동 속도를 올려 주는 동안은 무리하게 추격하지 말고 (W)\'영혼의 용광로\' 보호막으로 버티세요.', lv6: '메가 나르의 (R)\'나르!\'는 주위 모두를 집어던지고 벽에 부딪히면 기절시키니, 벽 가까이에서 메가 나르와 붙어 있지 마세요. 정면 교환이 위험한 메가 나르 상태를 피해 작은 나르일 때 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우세요. 나르가 변신 직후라면 라인을 밀고 포탑 쪽으로 빠져서 다음 교전을 기다리세요.', item: '나르는 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙겨 메가 나르의 폭발력을 버티세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 나르가 사거리에서 견제만 하는 구간에는 순간이동으로 안전하게 귀환한 뒤 라인에 합류할 수 있어요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'으로 막타를 쌓으며 성장하니 첫 웨이브부터 막타 경쟁을 압박하는 게 가장 중요해요. (Q)\'대량 학살 강타\'로 웨이브를 정리해 막타를 내주지 않고, 나서스가 Q를 쓰러 올 때 (E)\'학살자의 포효\'로 방어력을 깎으세요. 나서스는 (P)\'영혼의 포식자\'로 생명력 흡수를 얻으니 평타를 길게 맞대지 말고 짧게 끊으세요.', lv3: '(W)\'쇠약\'을 맞으면 이동 속도와 공격 속도가 점점 느려지니 기절에 걸린 동안은 나서스가 W를 쓸 수 없으니 (Q)\'대량 학살 강타\' 충전을 먼저 맞히는 쪽이 좋아요. 나서스의 (E)\'영혼의 불길\'이 깔린 지역에 서 있으면 방어력이 깎이니 그 지역 밖에서 (W)\'영혼의 용광로\' 보호막을 켜고 교환하세요. 나서스가 W를 쓴 시간에는 웨이브를 먼저 밀어 막타 차이를 벌려 두는 것이 좋아요.', lv6: '나서스가 (R)\'사막의 분노\'를 켜면 체력과 방어력, 마법 저항력이 올라 단단해지니, 켜진 동안은 교환하지 말고 지속이 끝날 때까지 빠지세요. 폭풍이 걷힌 직후가 붙을 기회이니 (R)\'멈출 수 없는 맹공\'의 긴 돌진으로 멀리서 달려들어 띄우고 (W)\'영혼의 용광로\'를 재시전하세요. 나서스는 후반에 강해지니 라인전에서 막타와 포탑 차이를 벌려 두는 게 핵심이에요.', item: '나서스는 방어력이 높아지고 오래 싸울수록 강해지니 강철심장으로 체력을 쌓고, 근처에 머무는 나서스에게 최대 체력 비례 추가 물리 피해를 넣으세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'영혼의 포식자\' 생명력 흡수와 회복을 눌러 초반 교환에서 이득을 굳히세요.' },
    '녹턴': { lv1: '(E)\'학살자의 포효\'를 사용해 상대의 방어력을 낮추고 둔화를 거세요. 녹턴이 (P)\'그림자 칼날\'로 체력을 회복하며 진입하는 것을 주의하며 거리를 유지해요. 첫 웨이브에서는 무리하게 싸우지 말고 미니언을 챙기세요.', lv3: '녹턴의 (Q)\'황혼의 인도자\'가 적중하면 이동 속도가 빨라지니 (W)\'영혼의 용광로\' 보호막으로 피해를 흡수하세요. (E)\'말할 수 없는 공포\'의 사거리 밖으로 벗어나 공포를 피한 뒤 (Q)\'대량 학살 강타\'를 충전해 기절시키세요. 상대의 (W)\'어둠의 장막\' 보호막이 빠진 것을 확인하고 공격하세요.', lv6: '(R)\'피해망상\'은 모든 적 챔피언의 시야 반경을 줄이니 합류하는 아군의 위치를 미리 확인해 두세요. 녹턴이 재사용으로 돌격해 오면 (Q)\'대량 학살 강타\'를 미리 충전해 두었다가 적중시키세요. 라인을 밀어 두고 상대의 궁극기 재사용 대기시간 동안 압박하세요.', item: '판금 장화와 가시 갑옷을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 가시 갑옷은 상대의 체력 회복을 억제하며 피해를 반사해요.', spell: '점멸과 순간이동을 추천해요. 빠른 합류와 생존 그리고 (Q)\'대량 학살 강타\'와의 연계를 위해 필요해요.' },
    '다리우스': { lv1: '다리우스는 (Q)\'학살\' 바깥 날에 맞으면 크게 아프고 (P)\'과다출혈\' 중첩이 쌓일수록 교환이 거칠어져요. 다리우스가 (Q)\'학살\'을 휘두를 때 도끼자루 쪽으로 붙거나 아예 범위 밖으로 비켜서서 (E)\'학살자의 포효\'를 먼저 맞히세요. 평타 교환이 길어지면 출혈이 쌓이니 짧게 교환하고 빠지세요.', lv3: '(E)\'포획\'에 끌려오면 (W)\'마비의 일격\' 둔화와 (Q)\'학살\'이 이어지니 다리우스의 E가 남아 있을 때는 깊이 들어가지 마세요. (E)\'포획\'을 뺀 뒤에 (Q)\'대량 학살 강타\'를 충전하면 다리우스는 나를 끌어당길 수단이 없어서 기절을 노리기 쉬워요. (W)\'영혼의 용광로\' 보호막은 출혈이 쌓이기 전에 켜서 짧은 교환에 쓰세요.', lv6: '(R)\'녹서스의 단두대\'는 중첩이 많을수록 강하니 출혈이 쌓인 채 체력이 낮은 상태로 다리우스 근처에 남지 마세요. 다리우스가 (Q)\'학살\'과 (E)\'포획\'을 다 쓴 뒤라면 (R)\'멈출 수 없는 맹공\'으로 달려가 띄우세요. 처치당하더라도 (P)\'영광스러운 죽음\'이 이어지니 마지막까지 평타를 붙이세요.', item: '다리우스는 물리 피해와 출혈이 핵심이라 태양불꽃 방패로 방어력과 체력을 챙기고, 평타 교환이 많아지면 가시 갑옷으로 이어가 상처를 걸어 두세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'학살\' 회복을 눌러야 체력이 남아 버티는 다리우스를 끊을 수 있어요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 쏘고 (W)\'룬 감옥\'으로 둔화를 걸며 거리를 유지하는 원거리 챔피언이에요. (Q)\'과부하\'는 첫 번째로 맞는 적에게 맞는 직선 스킬이라 미니언을 앞에 두고 서면 막을 수 있어요. (E)\'주문 전이\'에 맞아 표식이 남으면 (W)\'룬 감옥\'이 둔화 대신 속박으로 바뀌니 표식이 붙은 동안은 라이즈에게 다가가지 말고 표식이 사라진 뒤에 움직이세요.', lv3: '(W)\'룬 감옥\'에 속박되어도 스킬과 평타는 쓸 수 있으니 붙들렸다면 (W)\'영혼의 용광로\' 보호막을 켜고 버티세요. 표식이 없는 상태의 (W)\'룬 감옥\'은 둔화만 거니 라이즈가 E를 빼면 과감하게 (Q)\'대량 학살 강타\' 거리까지 붙으세요. 라이즈가 다른 스킬을 쓰면 (Q)\'과부하\'가 곧바로 다시 나가니 첫 스킬을 맞은 뒤에는 빠지는 쪽이 안전해요.', lv6: '(R)\'공간 왜곡\'으로 라이즈의 차원문 주변 아군이 순간이동해 오니, 라이즈가 문을 열면 정글러가 온다는 신호로 읽고 먼저 물러나세요. 라이즈가 (W)\'룬 감옥\'과 (E)\'주문 전이\'를 다 쓴 틈에 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우면 반격할 스킬이 많지 않아요. 체력이 낮아지면 라인을 밀고 포탑 쪽으로 물러서서 (W)\'룬 감옥\' 추격을 받지 않도록 하세요.', item: '라이즈는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기고, 붙어 있는 동안 불사르기로 피해를 더하세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 라이즈는 거리를 두고 싸우니 순간이동으로 귀환한 뒤 라인에 바로 복귀하는 편이 좋아요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'를 쏘고 (E)\'전기 작살\'로 둔화를 걸어서 초반 교환 화력이 높고, 스킬을 쓸수록 (P)\'고철장 거인\' 열기가 쌓여 위험 상태가 돼요. 열기가 가득 차 과열되면 몇 초간 스킬을 쓸 수 없으니 럼블이 스킬을 연달아 쓰는 모습을 보면 그 틈에 붙으세요. 교환은 럼블이 스킬을 쓴 직후에 하고 열기가 식을 시간은 주지 마세요.', lv3: '(W)\'고철 방패\'가 켜진 동안은 피해가 막히니 방패가 사라질 때까지 기다린 뒤에 (Q)\'대량 학살 강타\' 충전을 마치세요. (E)\'전기 작살\'에 맞으면 둔화와 마법 저항력 감소가 걸리지만 움직임 자체는 막히지 않으니 (W)\'영혼의 용광로\' 보호막을 켜고 계속 다가가세요. 럼블의 작살은 두 개까지 모아 두니 둘 다 쓰게 만든 뒤에 붙는 것이 좋아요.', lv6: '(R)\'이퀄라이저 미사일\'은 이번 패치에서 피해가 올라 화염의 벽을 지나는 동안 둔화와 피해를 크게 받으니, 벽을 따라 쫓아가지 마세요. 벽 밖에서 럼블이 궁극기를 쓰는 걸 보면 (R)\'멈출 수 없는 맹공\'으로 벽을 돌아 붙어 띄우세요. 럼블이 과열 상태로 스킬을 못 쓰는 틈이 가장 좋은 마무리 타이밍이에요.', item: '럼블의 피해는 거의 마법이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 럼블이 방패와 이동 속도로 빠지기 전에 점화로 마무리 피해를 확보하세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 웨이브를 밀며 체력을 회복하고, 분노가 쌓이면 (W)\'무자비한 포식자\' 기절이 길어져서 초반 교환이 가장 위험해요. 분노가 충분히 쌓인 레넥톤의 W는 보호막까지 부수니 (W)\'영혼의 용광로\' 보호막만 믿고 맞붙지 마세요. 레넥톤이 (E)\'자르고 토막내기\'로 돌진해 들어온 직후에 (E)\'학살자의 포효\'로 둔화를 걸고 평타 교환을 줄여 분노가 쌓이는 속도를 늦추세요.', lv3: '(W)\'무자비한 포식자\'를 쓴 레넥톤은 한동안 기절 연계가 끊기니 그 뒤에 (Q)\'대량 학살 강타\'를 충전해 붙으면 반격을 받을 위험이 줄어요. 레넥톤은 체력이 낮을수록 분노가 더 빨리 쌓이니 체력이 낮은 상태로 근접 교환을 길게 하지 마세요. 평타 교환보다 (E)\'학살자의 포효\'로 방어력을 깎고 짧게 끊어 치는 게 분노 상승을 늦춰요.', lv6: '레넥톤이 (R)\'강신\'을 켜면 추가 체력을 얻고 분노가 주기적으로 올라 강화된 스킬을 쓰기 쉬워지니 폭군 형태 동안은 교환을 피하세요. 폭군 형태가 풀려 분노가 줄어든 순간에 (R)\'멈출 수 없는 맹공\'으로 달려들고 (W)\'영혼의 용광로\'를 이어 터뜨리세요. 기절을 한 번 맞으면 연계가 이어지니 체력을 먼저 확인하고 들어가세요.', item: '레넥톤은 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙겨 기절 연계를 버티세요. 신발은 헤르메스의 발걸음으로 (W)\'무자비한 포식자\' 기절 시간을 줄이는 쪽을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'양떼 도륙\' 회복을 눌러야 분노가 쌓인 레넥톤과 교환을 이어갈 수 있어요.' },
    '렝가': { lv1: '렝가가 (P)\'보이지 않는 포식자\'를 통해 수풀에서 갑자기 도약하지 않도록 거리 조절을 하세요. (E)\'학살자의 포효\'로 렝가의 속도를 늦추고 방어력을 낮춘 뒤 짧게 딜교환을 하세요. 1~2레벨 구간은 상대의 폭발적인 피해가 강하므로 무리하게 다가가지 마세요.', lv3: '(E)\'올가미 투척\'은 처음 맞은 대상에게 둔화를 걸고 야성이 가득 차야 속박하니 (Q)\'대량 학살 강타\'를 충전하며 거리를 지키세요. 렝가가 도약해 들어오는 타이밍에 (W)\'영혼의 용광로\' 보호막을 켜서 피해를 흡수하세요. 야성 중첩이 쌓였을 때는 길게 맞붙지 말고 짧게 딜교환하세요.', lv6: '렝가가 (R)\'사냥의 전율\'로 위장한 동안에는 위치가 보이지 않으니 수풀 근처를 피하고, 도약해 모습을 드러낸 직후 (W)\'영혼의 용광로\' 보호막을 켜고 (Q)\'대량 학살 강타\'로 받아치세요. 도약 공격 이후 렝가가 (W)\'전투의 포효\'로 체력을 회복하며 버티려 하니 빠르게 거리를 벌리거나 아군 정글러를 부르세요. 라인을 당겨 수풀을 활용한 기습 공격에 노출되지 않도록 주의하세요.', item: '판금 장화와 가시 갑옷을 선택해요. 렝가의 기본 공격 피해를 줄이고 (W)\'전투의 포효\'의 회복 효과를 억제하기 위해서예요.', spell: '점멸과 점화를 추천해요. 렝가의 급격한 진입에 대응하고 (W)\'전투의 포효\'의 회복량을 줄여 처치하기 위해서예요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 세 번 이어 돌진하며 (P)\'룬 검\' 충전으로 평타 피해를 키우는 근접 교환형이에요. 리븐이 (Q)\'부러진 날개\'를 세 번 다 쓰고 나면 Q가 비니 그 직후에 (E)\'학살자의 포효\'를 맞히고 평타를 섞으세요. 리븐의 (W)\'기 폭발\'은 기절이라 근접해 있을 때가 가장 위험해요.', lv3: '(W)\'기 폭발\' 기절에 걸린 동안은 (W)\'영혼의 용광로\'를 켤 수 없으니 리븐이 붙기 전에 보호막을 켜 두세요. (E)\'용맹\'으로 피해를 막고 빠지는 리븐은 추격하기보다 (Q)\'대량 학살 강타\' 충전으로 도착 지점을 노리세요. 리븐이 (W)\'기 폭발\'을 쓰고 난 뒤라면 반격이 쉬우니 그때 짧게 교환하세요.', lv6: '(R)\'추방자의 검\'을 켠 리븐은 공격력과 사거리가 늘고 바람 가르기를 한 번 쏠 수 있으니, 지속 동안은 평타 사거리 밖에서도 맞을 수 있다고 생각하고 체력을 아끼세요. 리븐이 바람 가르기를 쓴 뒤라면 (R)\'멈출 수 없는 맹공\'으로 붙어 띄워 교환하세요. 체력이 낮은 리븐은 (E)\'용맹\'과 돌진으로 빠지니 정글러와 방향을 맞춰 도주로를 막으세요.', item: '리븐은 물리 피해 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발로는 (W)\'기 폭발\' 기절이 짧아지는 헤르메스의 발걸음이 어울려요.', spell: '점멸과 점화를 추천해요. 리븐이 돌진과 방패로 빠질 때 점화 피해가 마무리를 도와줘요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'으로 둔화를 걸며 거리를 유지하는 견제형이에요. 파편이 대상을 꿰뚫고 나가 뒤의 다른 적도 맞히니 미니언과 일렬로 서 있지 않도록 주의하세요. 웨이브를 밀어 두고 리산드라가 파편을 쓴 직후에 붙어 (E)\'학살자의 포효\'로 방어력을 깎으세요.', lv3: '(W)\'서릿발\'은 리산드라 주변의 적을 묶으니 가까이 붙을 때는 발이 묶여도 (W)\'영혼의 용광로\' 재시전은 쓸 수 있다는 점을 이용해 주변 피해로 맞받아치세요. (E)\'얼음갈퀴 길\'은 다시 시전하면 리산드라가 그 위치로 순간이동하니 도망갈 방향을 읽고 (Q)\'대량 학살 강타\'를 충전하세요. 리산드라가 E를 뺀 순간이 붙어서 기절을 노릴 때예요.', lv6: '(R)\'얼음 무덤\'은 적에게 쓰면 기절이고 자신에게 쓰면 무적이니 리산드라가 어느 쪽으로 쓰는지 보고 대응하세요. 자신에게 쓴 동안은 공격할 수 없는 상태가 되니 그 시간에 (R)\'멈출 수 없는 맹공\' 돌진을 낭비하지 마세요. 리산드라가 스킬을 모두 쓴 틈에 붙어 띄우면 도망칠 방법이 줄어요.', item: '리산드라는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기고, 붙어 있는 동안 불사르기로 피해를 더하세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 리산드라가 둔화로 견제하는 라인에서는 귀환 후 순간이동으로 복귀하는 편이 효율적이에요.' },
    '마스터이': { lv1: '마스터 이는 (P)\'2연속 공격\'으로 평타를 두 번 연달아 넣고 (E)\'우주류 검술\'로 평타에 추가 고정 피해를 붙이는 평타형이에요. 라인에서는 (Q)\'일격 필살\'로 가로지르며 때리고 빠지니 그 스킬이 빠진 순간에 (Q)\'대량 학살 강타\'로 압박하세요. 평타 교환이 길어지면 손해가 쌓이니 짧게 끊고 웨이브를 정리하세요.', lv3: '마스터 이는 (Q)\'일격 필살\'로 가로지르는 동안 대상으로 지정할 수 없지만 도착하면 다시 맞을 수 있으니, 그 직후의 위치에 범위 스킬을 준비하세요. (W)\'명상\'으로 체력을 회복하고 받는 피해를 줄이는 동안은 교환을 멈추고, 끝난 뒤에 (W)\'영혼의 용광로\' 보호막을 켜고 다시 붙으세요. 평타마다 고정 피해가 붙으니 방어력만 믿지 말고 체력을 같이 챙기세요.', lv6: '(R)\'최후의 전사\'는 모든 둔화 면역이라 (E)\'학살자의 포효\' 둔화는 통하지 않지만 기절은 통하니 (Q)\'대량 학살 강타\'를 충전해 맞히세요. 마스터 이가 (R)\'최후의 전사\'로 처치와 어시스트를 올리면 지속이 늘어나 위험하니 정글러와 함께 있을 때는 라인 밖으로 빠지세요. 마스터 이가 (Q)\'일격 필살\'을 쓴 직후에 (R)\'멈출 수 없는 맹공\'으로 붙어 띄워 끊으세요.', item: '마스터 이는 평타와 고정 피해가 중심이니 태양불꽃 방패로 방어력과 체력을 챙겨 오래 버티세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'명상\' 회복을 줄여야 마스터 이가 체력을 되찾고 버티는 걸 막을 수 있어요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 적을 뒤로 날리며 둔화를 걸고, (P)\'마법 흡수\'가 준비될 때마다 평타로 체력을 회복하는 탱커형이에요. 마오카이는 이번 패치에서 (Q)\'덤불 주먹\' 피해가 올라 견제가 아파졌고 라인에서 단단하게 버티니 (E)\'학살자의 포효\'로 방어력을 깎아 두고 막타를 챙기는 쪽에 집중하세요. (E)\'묘목 던지기\'로 수풀을 감시하는 마오카이를 의식해 수풀 쪽 웨이브 위치에서 무리하지 마세요.', lv3: '(W)\'뒤틀린 전진\'은 대상으로 도약해 속박하며 마오카이가 그동안 대상으로 지정할 수 없으니, 도약이 끝난 직후에 (W)\'영혼의 용광로\' 보호막을 켜서 교환하세요. 속박되어도 스킬과 평타는 쓸 수 있으니 붙어 있는 마오카이를 (Q)\'대량 학살 강타\'로 노리세요. 마오카이의 W가 빠진 뒤에 붙어 압박하세요.', lv6: '(R)\'대자연의 마수\'는 천천히 전진하면서 벽에 닿은 적을 속박하니 벽 쪽으로 도망가지 마세요. 마오카이가 궁극기를 쓴 뒤에는 방향이 정해져 있으니 (R)\'멈출 수 없는 맹공\'으로 옆에서 붙어 띄우세요. 마오카이는 단단하니 정글러가 올 때까지 무리하지 말고 라인을 밀어 압박하세요.', item: '마오카이는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 마오카이가 단단해 라인에서 끝내기 어려우니 순간이동으로 교전에 합류하는 가치가 커요.' },
    '말자하': { lv1: '말자하는 (Q)\'공허의 부름\'으로 침묵을 걸고 (W)\'공허의 무리\'로 웨이브를 정리하며 소모전을 이어가요. (P)\'공허 태세\'가 켜진 동안은 받는 피해가 크게 줄고 군중 제어에 면역이니, (E)\'학살자의 포효\'로 피해를 먼저 입혀 패시브를 깨 두세요. (Q)\'공허의 부름\'에 맞으면 침묵에 걸려 스킬을 쓸 수 없으니 두 개의 문에서 투사체가 나가는 위치를 보고 비켜서세요.', lv3: '(P)\'공허 태세\'는 피해를 입거나 군중 제어에 맞으면 잠시 후 사라지니, (E)\'학살자의 포효\'로 패시브를 깬 다음에 (Q)\'대량 학살 강타\' 기절을 맞히세요. (E)\'재앙의 환상\'은 맞은 동안 지속 피해를 주니 환상이 붙은 채로 길게 싸우지 말고 (W)\'영혼의 용광로\' 보호막으로 버티세요. 공허충이 몰려오니 말자하와 붙을 때는 웨이브가 적은 쪽에서 교환하세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화나 점멸로 풀 수 없고, 걸린 동안은 스킬과 평타도 못 쓰니 말자하가 궁극기를 쓸 수 있을 때는 단독으로 붙지 마세요. (P)\'공허 태세\'를 깬 뒤 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우면 공중에 뜬 동안은 말자하가 궁극기를 쓸 수 없으니 그 사이 연계를 이어가세요. 말자하가 패시브로 보호받는 구간에는 교환을 멈추고 피해로 패시브를 먼저 깨세요.', item: '말자하는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기고, 제압을 풀 수 있는 수은 장식띠를 두 번째로 고려하세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 말자하가 라인을 밀며 소모전을 하니 순간이동으로 귀환 후 웨이브를 되찾으세요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 처음 받는 피해를 막고 (Q)\'지진의 파편\'으로 견제하며 이동 속도를 훔쳐요. (Q)\'지진의 파편\'은 대상 지정이라 미니언 뒤에 숨어도 피할 수 없으니 맞아도 막타에 집중하세요. 평타로 보호막을 먼저 벗기고 (E)\'학살자의 포효\'로 방어력을 깎은 뒤에 교환하세요.', lv3: '(E)\'지면 강타\'는 공격 속도를 낮추고 (W)\'천둥소리\'는 평타를 강화하니 가까이서 오래 평타 교환을 하면 손해가 커요. 말파이트가 E를 쓴 직후에 (Q)\'대량 학살 강타\'를 충전해 기절을 노리는 짧은 교환이 좋아요. 보호막이 다시 생기기 전에 연속으로 때려야 효율이 좋아요.', lv6: '(R)\'멈출 수 없는 힘\'은 돌진하며 띄우는 저지 불가 돌진이라 군중 제어로 막을 수 없으니 정글러 근처에서는 말파이트의 궁극기 사거리 밖으로 위치를 잡으세요. 말파이트는 단단해서 처치가 어려우니 라인을 계속 밀고 성장 차이를 벌리세요. 궁극기를 쓴 말파이트는 도망칠 수단이 마땅치 않으니 그때 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우세요.', item: '말파이트는 단단하고 오래 싸우니 강철심장으로 체력을 쌓고 근처에 머무는 말파이트에게 최대 체력 비례 추가 피해를 주세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 단단한 말파이트를 라인전에서 끊을 화력을 더하세요.' },
    '모데카이저': { lv1: '모데카이저는 (Q)\'말살\'로 웨이브를 밀고 공격이나 스킬을 세 번 적중시키면 (P)\'암흑 탄생\' 오라가 켜져 추가 피해가 붙어요. 세 번째 적중을 쉽게 내주지 않도록 중간에 한 발 물러나 연속 적중을 끊으세요. (Q)\'말살\'은 단일 대상에게 맞으면 피해가 올라가니 미니언이 함께 맞는 위치에 서서 보너스를 피하는 것도 방법이에요.', lv3: '(W)\'불멸\'은 주고받는 피해를 흡수해 보호막을 채우니 길게 교환할수록 모데카이저의 보호막이 커져요. (E)\'죽음의 손아귀\'는 일정 지역의 적을 모두 끌어당기니 E가 남아 있을 때는 끌려올 위치를 피하고, E를 뺀 뒤에 (Q)\'대량 학살 강타\'를 충전해 기절을 노리세요. 짧게 교환하고 빠지는 쪽이 (W)\'영혼의 용광로\' 보호막을 아끼는 법이에요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 순간이동이나 궁극기로는 빠져나갈 수 없고 수은 장식띠로도 풀 수 없으니, 모데카이저의 궁극기가 준비된 동안은 체력을 높게 유지하세요. 끌려가면 정글러의 도움 없이 일대일로 싸워야 하니 체력이 밀린 상태에서는 모데카이저에게 다가가지 마세요. 모데카이저가 (E)\'죽음의 손아귀\'를 이미 쓴 뒤라면 (R)\'멈출 수 없는 맹공\'으로 달려들어 띄워 반격 수단을 줄이세요.', item: '모데카이저는 마법 피해가 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 모데카이저는 웨이브를 밀어 두는 일이 많아 순간이동으로 라인을 되찾기 좋아요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'을 던져 현재 체력에 비례한 피해와 둔화를 주는 직선 스킬로 견제해요. 뼈톱은 처음 맞는 적에게 맞으니 미니언을 앞에 두고 서면 막을 수 있어요. (P)\'가고 싶은 데로 간다\'는 처음 적중하는 기절 같은 이동 불가 효과에 저항하니 패시브가 준비된 동안은 (Q)\'대량 학살 강타\' 기절이 제대로 들어가지 않을 수 있다고 생각하세요.', lv3: '(W)\'심장 전기 충격\'은 받은 피해를 저장했다가 터뜨리니 문도 박사가 W를 켠 동안은 정면에서 때리지 말고 효과가 끝날 때쯤 다시 붙으세요. 패시브로 한 번 저항하면 재사용 대기시간 동안은 다시 저항하지 못하니 저항이 빠진 틈에 (Q)\'대량 학살 강타\' 기절을 맞히세요. 바닥에 떨어진 통은 문도 박사가 주워 체력을 회복하니 통 근처에서는 교환하지 마세요.', lv6: '(R)\'최대 투여량\'은 체력을 즉시 회복하고 이동 속도와 긴 회복까지 주니 문도 박사가 궁극기를 쓰기 전에 (R)\'멈출 수 없는 맹공\'으로 먼저 띄워 큰 피해를 넣고 끝내는 게 좋아요. 궁극기를 쓴 뒤에는 오래 회복하니 무리하게 쫓지 말고 라인을 밀며 기다리세요. 체력이 낮아진 문도 박사는 (E)\'둔기에 의한 외상\'이 강해지니 아슬하게 버티는 상대에게 무작정 붙지 마세요.', item: '문도 박사는 체력에 비례하는 피해와 회복으로 오래 버티니 강철심장으로 체력을 쌓고 근처에 머무는 상대에게 최대 체력 비례 추가 피해를 주세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 문도 박사의 회복량을 줄여야 (R)\'최대 투여량\' 이후에도 끝낼 수 있어요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'을 오래 조준할수록 사거리와 피해가 늘어나는 원거리 챔피언이에요. 길게 조준하는 모습이 보이면 직선에서 옆으로 비켜서고, 화살이 나간 직후에 거리를 좁혀 (E)\'학살자의 포효\'를 맞히세요. (E)\'퍼붓는 화살\'로 깔린 오염 지면은 이동 속도를 줄이고 회복을 감소시키니 그 위로 걸어 들어가지 마세요.', lv3: '바루스는 평타로 (W)\'역병 화살\' 역병을 쌓고 다른 스킬로 터뜨려 최대 체력 비례 마법 피해를 주니, 역병이 붙은 뒤에는 바루스의 스킬 사거리 안에 오래 남지 마세요. 붙은 뒤에는 바루스가 (E)\'퍼붓는 화살\'을 쏘기 전에 (Q)\'대량 학살 강타\' 기절을 맞혀 교환 시간을 줄이세요. 원거리인 바루스는 미니언 뒤에서 막타를 치니 (E)\'학살자의 포효\'로 미니언을 밀어 방어력을 깎아 두세요.', lv6: '(R)\'부패의 사슬\'은 처음 맞은 적 챔피언의 이동을 차단하고 감염되지 않은 주변 챔피언에게 계속 퍼지니, 정글러와 붙어 서 있으면 함께 걸릴 수 있어요. 바루스는 (P)\'죽지 않는 복수심\'으로 처치나 어시스트 뒤 공격력과 주문력이 올라가니 아군과 맞교환하는 싸움은 피하세요. 바루스의 (Q)\'꿰뚫는 화살\'을 빗나가게 만든 직후가 (R)\'멈출 수 없는 맹공\'으로 달려들 틈이에요.', item: '바루스는 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 바루스에게 붙은 뒤 점화로 마무리하면 도망치려 해도 끊을 수 있어요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 조절하며 강화 평타를 넣고, 같은 대상에게 세 번째 공격이 맞으면 (W)\'은화살\'이 최대 체력 비례 고정 피해를 줘요. 세 번째 적중을 허용하지 않도록 두 번 맞았다면 한 박자 물러나 베인의 공격 순서를 끊으세요. 베인이 앞으로 나와 막타를 치려 할 때 (E)\'학살자의 포효\'로 방어력을 깎아 두세요.', lv3: '(E)\'선고\'는 대상을 뒤로 날려 지형에 부딪히면 추가 피해와 기절을 주니 벽 가까이에서 베인과 맞서지 마세요. 베인이 E를 쓴 직후에는 (Q)\'대량 학살 강타\'를 충전하며 붙어도 밀려날 걱정이 줄어요. (Q)\'구르기\'로 빠지는 베인은 쫓지 말고 구르기 방향을 보고 (E)\'학살자의 포효\'를 던지세요.', lv6: '(R)\'결전의 시간\'을 켜면 구르기 때 투명해지고 이동 속도 증가가 더 커져 접근과 후퇴가 모두 빨라지니 그 동안은 교환하지 마세요. 베인이 궁극기를 쓴 직후라도 벽을 등지고 있을 때는 (E)\'선고\'가 위험하니 벽에서 떨어져서 (R)\'멈출 수 없는 맹공\'으로 붙으세요. 투명 구르기로 사라진 뒤에 베인이 평타를 시작하면 그 순간 (W)\'영혼의 용광로\' 보호막을 켜세요.', item: '베인은 물리 피해 중심이라 태양불꽃 방패로 방어력과 체력을 챙기고 최대 체력 비례 고정 피해를 받아도 버티세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 베인은 접근 이동 속도가 빠르니 유체화로 거리를 좁히는 데 도움이 돼요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 접근하면서 이동 속도를 올리고 처음 평타를 맞은 대상을 기절시키는 근접 교환형이에요. 볼리베어가 다가올 때 (E)\'학살자의 포효\'를 먼저 맞혀 방어력을 깎아 두고, 기절 평타를 맞는 순간을 피하도록 한 발 뒤로 빼세요. 볼리베어의 (P)\'무자비한 폭풍\'은 공격 속도가 쌓이니 평타 교환을 길게 하지 마세요.', lv3: '(W)\'광란의 상처\'로 표식을 남긴 뒤 다시 쓰면 추가 피해와 회복이 붙으니 표식이 남은 상태에서는 교환을 이어가지 말고 빠지세요. 볼리베어가 (Q)\'번개 강타\'를 쓴 뒤에 (Q)\'대량 학살 강타\'를 충전해 맞히면 반격이 어렵고, 아직 쓰지 않았다면 먼저 (W)\'영혼의 용광로\' 보호막을 켜세요. (E)\'천공 분열\'이 떨어지는 지점은 피하되 볼리베어가 폭발 반경 안에서 보호막을 얻는다는 점을 기억하세요.', lv6: '(R)\'폭풍을 부르는 자\'는 지정한 위치로 도약해 둔화와 피해를 주고 추가 체력을 얻으니 볼리베어가 궁극기를 쓰는 순간 착지 지점에서 벗어나세요. 궁극기를 쓴 볼리베어는 추가 체력으로 단단해지니 지속 중에는 교환하지 말고, 끝난 뒤에 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우세요. 포탑이 일시적으로 꺼질 수 있으니 포탑 아래에서도 안전하다고 생각하지 마세요.', item: '볼리베어는 물리와 마법 피해가 섞여 있고 근접 교환이 길어지니 강철심장으로 체력을 쌓으세요. (Q)\'번개 강타\' 기절이 아프니 신발은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 볼리베어가 도약으로 합류하는 구도라 순간이동으로 맞대응하기 좋아요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 흡수하며 견제하는 마법 피해 챔피언이에요. (Q)\'수혈\'은 대상 지정이라 미니언 뒤에 서서 피할 수 없으니 맞더라도 계속 웨이브를 밀며 버티세요. (E)\'선혈의 파도\'는 적 유닛이 가로막을 수 있으니 미니언을 사이에 끼우고 서면 막을 수 있어요.', lv3: '(W)\'피의 웅덩이\'로 변한 동안 블라디미르는 공격 대상이 되지 않으니 웅덩이가 풀릴 때까지 평타나 스킬을 낭비하지 마세요. 블라디미르가 W를 쓰고 난 뒤에는 피해를 피할 수단이 빠지니 그때 (E)\'학살자의 포효\'와 (Q)\'대량 학살 강타\'를 이어서 맞히세요. 웅덩이 위에 서 있으면 이동 속도가 느려지고 체력을 빨리니 바닥을 보고 벗어나세요.', lv6: '(R)\'혈사병\'에 감염되면 일정 시간 더 큰 피해를 입고 몇 초 뒤 터지니 영역에서 빠져나오고 감염 중에는 교환하지 마세요. 블라디미르는 맞은 챔피언 수에 비례해 회복하니 정글러와 함께 서 있을 때 같이 감염되지 않도록 거리를 벌리세요. 블라디미르가 (W)\'피의 웅덩이\'로 숨은 직후에는 서두르지 말고, 웅덩이가 풀린 뒤에 (R)\'멈출 수 없는 맹공\'으로 띄워 끊으세요.', item: '블라디미르는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'수혈\'과 웅덩이 회복을 눌러야 체력 싸움에서 이길 수 있어요.' },
    '뽀삐': { lv1: '뽀삐는 (Q)\'망치 강타\'로 둔화 지대를 깔고 (P)\'강철의 외교관\' 방패를 줍고 보호막을 얻으며 버텨요. 뽀삐의 (E)\'용감한 돌진\'은 대상을 밀어내 지형에 부딪히면 기절시키니 벽 가까이에서 싸우지 마세요. 뽀삐가 방패를 던지고 주우러 가는 사이에 (E)\'학살자의 포효\'를 맞히고 웨이브를 정리하세요.', lv3: '(W)\'굳건한 태세\'는 기본 지속 효과로 방어력과 마법 저항력을 주고 켜면 이동 속도가 오르니, 뽀삐가 W를 켜고 다가오면 무리하게 맞서지 말고 효과가 끝난 뒤에 교환하세요. 뽀삐가 E를 뺀 직후에 (Q)\'대량 학살 강타\'를 충전하면 기절을 노리기 좋아요. (W)\'영혼의 용광로\' 보호막은 뽀삐의 (Q)\'망치 강타\' 지대가 터지기 직전에 켜세요.', lv6: '(R)\'수호자의 심판\'은 정신을 집중한 뒤 망치를 휘둘러 굉장히 멀리 날려 버리니 맞으면 교전에서 멀리 떨어져 나가고 상대 정글러 쪽으로 날아가면 더 위험해요. (W)\'굳건한 태세\'는 주변에서 돌진하는 적을 막는 스킬이니 (R)\'멈출 수 없는 맹공\'은 뽀삐가 W를 쓴 뒤에 들어가는 편이 안전해요. 벽에 몰릴 때는 (E)\'용감한 돌진\' 기절이 겹치지 않게 위치를 잡으세요.', item: '뽀삐는 (W)\'굳건한 태세\' 기본 지속 효과와 방패 보호막으로 단단하니 강철심장으로 체력을 쌓고 근처에 머무는 뽀삐에게 추가 피해를 주세요. 신발은 (E)\'용감한 돌진\' 벽 기절 시간을 줄여 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 뽀삐가 라인에서 오래 버티는 만큼 순간이동으로 교전에 합류하는 가치가 커요.' },
    '사일러스': { lv1: '사일러스는 (Q)\'사슬 후려치기\'로 둔화를 걸고 (P)\'페트리사이트 폭발\' 충전 평타로 추가 마법 피해를 넣으며 교환하는 챔피언이에요. 사일러스가 스킬을 쓰면 다음 평타가 강해지고 공격 속도도 올라가니 스킬 직후의 평타 교환은 피하세요. 사일러스가 W로 돌진해 회복하는 순간을 노려 (E)\'학살자의 포효\'를 맞히세요.', lv3: '(W)\'국왕시해자\'로 붙어 피해를 주고 회복하는 사일러스에게는 (Q)\'대량 학살 강타\'를 충전해 돌진 끝 위치에 맞히면 기절 각이 나와요. (E)\'억압\'은 다시 쓰면 사슬을 던져 맞은 적 방향으로 사일러스가 이동하니 사슬이 날아오는 직선에서 비켜서세요. 사슬 폭발이 터지는 지점은 피하되 (W)\'영혼의 용광로\' 보호막은 평타 교환 직전에 켜세요.', lv6: '(R)\'강탈\'은 내가 궁극기를 썼는지와 상관없이 훔쳐 가니 사일러스가 (R)\'멈출 수 없는 맹공\'을 가져가 돌진기로 쓸 수 있다는 점을 기억하세요. 사일러스의 체력이 낮고 W 회복이 빠졌을 때 먼저 붙어 띄우고 끝내는 쪽이 안전해요. 훔쳐 간 궁극기로 멀리서도 돌진해 올 수 있으니 라인을 너무 당기지 말고 포탑 쪽에서 받아내세요.', item: '사일러스는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'국왕시해자\' 회복을 눌러야 사일러스와 길게 붙을 수 있어요.' },
    '세주아니': { lv1: '1~2레벨에는 세주아니의 (Q)\'혹한의 맹습\' 돌진에 주의하며 거리를 유지해요. (E)\'학살자의 포효\'를 사용해 방어력을 낮추며 미니언과 함께 견제하며 버텨요.', lv3: '(Q)\'혹한의 맹습\'에 맞아 공중에 뜬 동안에는 스킬을 쓸 수 없으니, 띄우기가 끝나고 세주아니가 멈춘 자리에서 (Q)\'대량 학살 강타\'를 충전해 반격하세요. (W)\'혹한의 서릿발\'이 서리 중첩을 쌓아 (E)\'만년 서리\' 기절로 이어지니 근접 교환을 길게 끌지 마세요. (W)\'영혼의 용광로\'로 보호막을 얻어 딜교환을 받아내요.', lv6: '(R)\'빙하 감옥\'은 처음 맞은 챔피언을 기절시키는 올가미이니 이 스킬을 쓴 직후에 진입하세요. (R)\'멈출 수 없는 맹공\'은 이동 거리에 비례해 기절시키니 충분히 달린 뒤 부딪히세요. 세주아니가 (E)\'만년 서리\' 중첩을 쌓기 전에 싸움을 걸거나 정글러의 지원을 요청해요.', item: '헤르메스의 발걸음과 강철심장을 선택해요. 세주아니의 마법 피해를 버티고 체력을 높여서 전투를 길게 가져가기 위해서예요.', spell: '점멸과 정화를 추천해요. 정화는 (R)\'빙하 감옥\'과 (E)\'만년 서리\'의 기절을 풀 수 있지만 (Q)\'혹한의 맹습\'의 띄우기는 풀지 못해요.' },
    '세트': { lv1: '세트는 평타를 양 주먹으로 번갈아 때리고 (P)\'투기장의 투지\'로 잃은 체력에 비례해 회복해서 근접 교환에서 오래 버텨요. (Q)\'주먹다짐\'은 다음 두 번의 공격에 최대 체력 비례 피해를 더하니 세트가 다가오는 순간 (E)\'학살자의 포효\'로 방어력을 깎고 한 번은 피하세요. 체력이 낮을수록 회복이 커지니 끝낼 수 없는 교환을 길게 끌지 마세요.', lv3: '(E)\'안면 강타\'는 양옆의 적을 끌어당겨 기절시키니 세트 양옆에 나와 미니언이 함께 걸리는 위치를 피하세요. (W)\'강펀치\'는 받은 피해를 투지로 모아 보호막과 피해로 돌려주니 세트가 맞은 피해를 쌓는 동안은 교환을 쉬고, 쓰고 난 뒤에 (Q)\'대량 학살 강타\'로 붙으세요. (W)\'영혼의 용광로\' 보호막은 세트의 기절 연계가 오기 전에 켜 두세요.', lv6: '(R)\'대미 장식\'은 적 하나를 잡아 공중에서 내리꽂고 착지 지점의 적을 둔화시키니 정글러와 뭉쳐 서 있지 마세요. 세트가 (W)\'강펀치\'로 투지를 쓰고 난 직후가 (R)\'멈출 수 없는 맹공\'으로 달려들 가장 좋은 시간이에요. 세트가 체력이 낮아 보여도 회복이 크니 교전을 길게 끌지 말고 한 번에 끝낼 각에서만 붙으세요.', item: '세트는 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 헤르메스의 발걸음을 골라 (E)\'안면 강타\' 기절을 조금이라도 짧게 받으세요.', spell: '점멸과 점화를 추천해요. 점화로 세트의 회복을 눌러 체력이 낮은 세트를 끊을 수 있어요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 대상 최대 체력에 비례한 피해를 주고 스킬을 쓸 때마다 (P)\'기 보호막\'을 얻으며 버텨요. 쉔이 스킬로 챔피언을 맞히면 보호막 재사용 대기시간이 줄어드니 쉔의 스킬이 빠진 시간에 막타를 챙기세요. 기의 검에 부딪히면 쉔에게서 달아날 때 둔화되니 직선 위에서 비켜서세요.', lv3: '(E)\'그림자 돌진\'은 경로상의 적을 도발해 쉔을 때리게 만들고 도발 중에는 스킬을 쓸 수 없으니 쉔의 E가 남아 있을 때는 (Q)\'대량 학살 강타\' 충전을 오래 하지 마세요. 쉔이 E를 쓴 뒤에는 붙어서 (E)\'학살자의 포효\'로 방어력을 깎고 짧게 교환하세요. (W)\'의지의 결계\'가 펼쳐진 동안은 쉔이나 기의 검 근처 아군에 대한 공격이 차단되니 그 사이 평타를 낭비하지 말고 결계가 끝난 뒤에 교환하세요.', lv6: '(R)\'단결된 의지\'는 쉔이 공격받는 아군에게 순간이동하고 보호막을 주니 쉔이 사라지면 다른 라인의 교전이 시작된 신호로 보고 라인을 밀어 두세요. 쉔이 궁극기를 쓴 직후에는 라인에 없으니 포탑 압박이나 정글 개입을 할 시간이 생겨요. 쉔의 E가 빠진 시간에는 도발 걱정 없이 (R)\'멈출 수 없는 맹공\'으로 붙어 띄울 수 있어요.', item: '쉔은 체력 비례 피해와 보호막으로 버티니 강철심장으로 체력을 쌓아 근처에 머무는 쉔에게 추가 피해를 주세요. 신발은 도발 같은 군중 제어를 줄여 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 쉔이 궁극기로 다른 라인에 합류하는 만큼 순간이동으로 맞대응하기 좋아요.' },
    '쉬바나': { lv1: '첫 웨이브에서는 (Q)\'잉걸불 일격\'의 강력한 기본 공격 피해를 조심하며 거리를 유지하세요. (E)\'학살자의 포효\'를 먼저 사용하여 상대의 속도를 늦추고 방어력을 낮춘 뒤 짧게 딜교환을 해요. 무리하게 붙지 말고 경험치만 챙기며 체력을 관리하세요.', lv3: '상대의 (E)\'용암 분출\'이 빠진 타이밍에 (Q)\'대량 학살 강타\'를 충전해 띄워 올리는 구도를 잡으세요. (W)\'지옥불 방패\'를 켜고 접근하는 상대에게 (W)\'영혼의 용광로\' 보호막으로 피해를 흡수하고 폭발 피해를 입히세요. 상대의 기본 공격 사거리가 짧으므로 스킬을 맞힌 후 빠르게 빠져나오는 것이 좋아요.', lv6: '상대가 (R)\'용의 강림\'으로 변신해 진입할 때 (R)\'멈출 수 없는 맹공\'을 사용해 저지 불가 상태로 맞서세요. 용 형상일 때의 강화된 (E)\'용암 분출\'은 범위가 넓고 관통하므로 무리하게 정면에서 버티지 마세요. 라인을 밀어 넣고 정글러를 호출하여 함께 상대의 체력을 깎는 전략이 효율적이에요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 추천해요. 상대의 마법 피해를 줄이고 둔화와 공포 지속시간을 줄여야 하며 체력과 방어력을 높여 버텨야 해요.', spell: '점멸과 점화를 추천해요. 상대가 (W)\'지옥불 방패\'로 체력을 회복하는 것을 억제하고 킬각을 잡기 좋아요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 번개를 퍼뜨리고 (W)\'제국의 눈\'으로 둔화를 걸며 마법 피해로 견제하는 챔피언이에요. 스웨인이 (E)\'속박명령\' 파동을 던지기 전에 거리를 좁히는 쪽이 중요하고, 미니언이 많은 웨이브에서는 (E)\'학살자의 포효\'로 미니언을 밀어 뒤의 스웨인을 맞히세요. 스웨인의 (P)\'굶주린 새떼\'는 영혼 조각으로 체력을 회복하니 오래 소모전을 하지 마세요.', lv3: '(E)\'속박명령\'은 파동이 돌아오면서 맞은 적을 속박하고 이후 끌어당길 수 있으니 속박되어도 스킬은 쓸 수 있다는 점을 이용해 (W)\'영혼의 용광로\' 보호막을 켜세요. 스웨인이 E를 뺀 뒤에 (Q)\'대량 학살 강타\'를 충전해 붙으면 도망갈 수단이 줄어요. 스웨인의 (W)\'제국의 눈\'은 둔화를 걸어 추격과 도주를 모두 어렵게 하니 맞은 직후에는 무리하게 붙지 마세요.', lv6: '(R)\'악의 승천\'은 악마로 변신해 근처 적의 생명력을 흡수하니 변신한 스웨인은 오래 버티고, 지속이 길어지니 무리해서 쫓지 마세요. 스웨인이 (R)\'악의 승천\'을 켜기 전에 (E)\'속박명령\'을 빗나가게 만든 뒤 (R)\'멈출 수 없는 맹공\'으로 달려드세요. 변신 중에는 (E)\'속박명령\' 재사용 대기시간이 짧아져 더 자주 날아오니 속박되면 (W)\'영혼의 용광로\' 보호막으로 버티세요.', item: '스웨인은 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 스웨인의 회복을 눌러야 (R)\'악의 승천\' 뒤에도 마무리가 돼요.' },
    '스카너': { lv1: '1~2레벨 구간에는 (Q)\'부서진 대지/지반 돌출\'의 둔화와 피해를 조심하며 미니언을 챙겨요. (Q)\'대량 학살 강타\'를 사용하여 거리를 조절하며 견제하세요. 스카너가 (E)\'이쉬탈의 격돌\'로 돌진해올 수 있으니 무리한 진입은 피해요.', lv3: '스킬이 모인 후에는 (Q)\'대량 학살 강타\'를 적중시켜 딜교환을 시도해요. 스카너가 (E)\'이쉬탈의 격돌\'을 사용하여 돌진할 때 (W)\'영혼의 용광로\'를 사용해 피해를 줄여야 해요. (E)\'학살자의 포효\'로 방어력을 낮추며 전투를 이어가세요.', lv6: '(R)\'꿰뚫기\'에 맞으면 제압되어 스킬과 점멸과 정화를 모두 쓸 수 없으니 맞기 전에 (W)\'영혼의 용광로\' 보호막을 미리 켜 두세요. (E)\'이쉬탈의 격돌\'은 끌고 가서 벽에 부딪히면 기절시키니 벽 근처에서 붙잡히지 않게 서세요. 라인을 빠르게 밀어 넣고 정글러를 불러 스카너의 압박을 줄여요.', item: '강철심장과 헤르메스의 발걸음을 선택하세요. 헤르메스의 발걸음의 강인함은 (E)\'이쉬탈의 격돌\' 기절과 둔화 지속시간을 줄이지만 (R)\'꿰뚫기\' 제압은 줄이지 못해요. 강철심장은 체력을 높여 오래 버티게 해요.', spell: '점멸과 점화를 추천해요. 스카너 스킬에는 회복 수단이 없으니 점화는 마무리 피해로 킬각을 만드는 용도로 써요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'로 지나간 자리에 독구름을 남겨 추격과 견제를 동시에 하는 챔피언이에요. 독구름이 깔린 곳에 들어가면 피해를 받으니 신지드 뒤를 졸졸 쫓지 말고 웨이브 정리로 압박하세요. 신지드의 (P)\'독성 급류\'는 가까운 챔피언을 피해 이동 속도를 올리니 가까이 붙어서 압박해도 따라잡기 어려울 수 있어요.', lv3: '(W)\'초강력 접착제\'는 위를 지나는 적을 둔화시키고 이동 스킬을 못 쓰게 하니 접착제 위로 걸어 들어가 싸우지 마세요. (E)\'던져넘기기\'로 신지드 뒤로 날아가 접착제에 착지하면 속박되니 접착제 방향으로 던져지지 않도록 위치를 잡으세요. 신지드가 (E)\'던져넘기기\'를 쓰려고 가까이 붙는 순간을 노려 (Q)\'대량 학살 강타\' 충전을 맞히세요.', lv6: '(R)\'광기의 물약\'을 마신 신지드는 전투 능력이 올라가고 독이 더 아프니 지속 중에는 교환을 피하세요. 신지드가 (W)\'초강력 접착제\'를 쓴 뒤에는 접착제가 깔린 자리를 피해 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우세요. 독구름을 지나가는 추격은 손해가 되니 신지드가 도망가면 포탑 앞에서 멈추세요.', item: '신지드는 독과 마법 피해가 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 (W)\'초강력 접착제\' 둔화를 줄여 주는 신속의 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 신지드의 도망 직전 마무리 피해를 확보하세요.' },
    '아이번': { lv1: '(Q)\'덩굴뿌리\'에 맞아 속박되지 않도록 적절한 거리를 유지하며 라인을 받아내세요. (W)\'영혼의 용광로\'를 사용해 보호막을 얻고 상대의 견제를 견디며 체력을 관리해요.', lv3: '상대의 (Q)\'덩굴뿌리\'를 피한 뒤 (Q)\'대량 학살 강타\'를 충전해 기절을 노리며 진입하세요. 아이번이 (E)\'보호의 씨앗\'으로 보호막을 얻으면 무리하게 딜교하지 말고 다시 거리를 벌려요. (E)\'학살자의 포효\'로 둔화를 걸어 다음 공격을 준비해요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태이므로 아이번의 (Q)\'덩굴뿌리\'를 무시하고 돌진하세요. 소환된 (R)\'데이지!\'의 공격을 주의하며 (Q)\'대량 학살 강타\'로 적을 띄워 킬을 노려요. 라인 상황을 살피며 정글러와 함께 움직이세요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 가세요. 헤르메스의 발걸음은 마법 저항력과 강인함을 제공하며 태양불꽃 방패는 체력과 방어력을 높여줘요.', spell: '점멸과 점화를 선택해요. 점멸은 거리를 조절하거나 진입할 때 사용하고 점화는 적의 체력을 깎아 킬을 따기 위해 써요.' },
    '아지르': { lv1: '1~2레벨 구간에서는 아지르의 (Q)\'사막의 맹습\' 견제를 조심하며 미니언 근처에서 거리를 유지하세요. (W)\'영혼의 용광로\'를 사용하여 보호막을 얻으면 상대의 초반 견제를 조금 더 수월하게 받아낼 수 있어요. 무리하게 다가가지 말고 최대한 체력을 보존하며 파밍에 집중하세요.', lv3: '(W)\'일어나라!\'의 모래 병사는 근처 적에게 일직선으로 마법 피해를 주니 병사 근처에서 평타 교환을 길게 하지 마세요. (E)\'신기루\'는 보호막을 얻고 모래 병사에게 질주하니 질주가 끝난 직후 충전한 (Q)\'대량 학살 강타\'를 맞히세요. (E)\'학살자의 포효\'로 둔화를 걸어 상대가 빠지기 전에 딜교환을 마무리하세요.', lv6: '아지르의 (R)\'황제의 진영\'은 적을 밀어내고 병사들이 남아 길을 가로막으니, 궁극기가 빠진 것을 확인한 뒤 (R)\'멈출 수 없는 맹공\'으로 진입하세요. 진입한 뒤에는 (Q)\'대량 학살 강타\'로 띄워 올리며 킬을 노릴 수 있어요. 라인을 빠르게 밀어넣고 정글러를 불러 함께 압박하는 것이 좋아요.', item: '헤르메스의 발걸음과 강철심장을 선택하세요. 아지르의 마법 피해를 줄이고 체력을 높여 전투를 길게 가져가기 위해서예요.', spell: '점멸과 유체화를 추천해요. 아지르의 거리를 좁혀서 (Q)\'대량 학살 강타\'를 맞히기 위해 필요해요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 둔화를 걸고 (E)\'표창곡예\'로 표식을 남겨 이어 붙는 견제 위주의 챔피언이에요. 스킬로 챔피언을 맞히면 주변에 원이 생기고, 그 경계를 넘어가면 다음 평타의 사거리와 피해가 늘어나니 원을 넘나드는 위치를 조심하세요. 아칼리가 막타를 치려 앞으로 나올 때 (E)\'학살자의 포효\'를 맞혀 방어력을 깎으세요.', lv3: '(W)\'황혼의 장막\'은 투명 상태로 대상 지정을 막지만 (Q)\'대량 학살 강타\'와 (E)\'학살자의 포효\'는 지정형이 아니라 연막 안에서도 맞아요. (E)\'표창곡예\' 표식이 남은 뒤 다시 쓰면 아칼리가 돌진하니 표식이 붙은 동안은 (W)\'영혼의 용광로\' 보호막을 켜고 버티세요. 아칼리가 스킬을 쓰면 잠깐 모습이 드러나니 그 순간이 반격 타이밍이에요.', lv6: '(R)\'무결처형\'은 도약해 적을 맞히고 재사용하면 돌진까지 이어지니 아칼리의 궁극기가 준비된 동안은 체력을 높게 유지하세요. 아칼리가 (W)\'황혼의 장막\'을 쓰고 난 뒤라면 연막이 빠진 빈틈에 (R)\'멈출 수 없는 맹공\'으로 달려들어 띄우세요. 연막 안의 아칼리는 보이지 않으니 연막 안으로 무작정 따라 들어가지 말고 범위 스킬인 (W)\'영혼의 용광로\' 재시전을 연막 쪽에 맞추세요.', item: '아칼리는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙겨 불사르기로 붙어 있는 동안 피해를 보태세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 아칼리가 연막과 도약으로 빠지기 쉬워 점화로 마무리 피해를 확보하세요.' },
    '아크샨': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\' 견제가 심하므로 무리하게 진입하지 마세요. (W)\'영혼의 용광로\' 보호막으로 피해를 흡수하며 미니언을 챙기는 데 집중하세요. 최대한 거리 조절을 하며 체력을 보존하는 것이 중요해요.', lv3: '상대의 (E)\'영웅의 비상\' 이동 경로를 예측해 (E)\'학살자의 포효\'로 둔화를 먼저 거세요. 이후 (Q)\'대량 학살 강타\'를 충전해 적중시켜 기절시키는 구도를 만드세요. 아크샨이 갈고리를 썼을 때 빠르게 접근해 딜교환을 시도하세요.', lv6: '(R)\'멈출 수 없는 맹공\'으로 거리를 좁혀 강하게 압박하고 킬각을 노리세요. 체력이 낮을 때 (R)\'인과응보\'에 맞으면 순식간에 처치될 수 있으니 주의하세요. 라인을 당겨 정글러를 부르면 아크샨을 쉽게 잡아낼 수 있어요.', item: '판금 장화와 강철심장을 가세요. 기본 공격 피해를 줄여주고 최대 체력을 늘려 버티기 좋기 때문이에요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀를 빠르게 하고 점멸로 변수를 만들어야 해요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\'을 세 번 휘두르고 (E)\'파멸의 돌진\' 기본 지속 효과로 적 챔피언에게 피해를 입힐 때 체력을 회복해서 첫 교환이 거칠어요. 세 번의 휘두름은 범위가 서로 다르니 휘두르는 모양을 보고 한 번씩 위치를 옮겨 피하고 평타 교환은 짧게 끊으세요. 아트록스가 Q를 다 쓴 뒤에는 (E)\'학살자의 포효\'를 맞히고 압박하세요.', lv3: '(W)\'지옥사슬\'은 맞은 뒤 일정 시간 안에 지역을 벗어나지 않으면 중앙으로 끌려가 다시 피해를 받으니 맞았다면 바로 원 밖으로 빠져나오세요. 아트록스가 (E)\'파멸의 돌진\'을 쓴 직후에 (Q)\'대량 학살 강타\'를 충전해 붙으면 도착 위치를 노릴 수 있어요. (P)\'사신 태세\' 평타가 강하게 나가는 주기를 보고 그 타이밍엔 교환을 쉬세요.', lv6: '(R)\'세계의 종결자\'는 공격력과 회복량, 이동 속도를 올리고 챔피언 처치에 관여하면 지속이 늘어나니 켜진 아트록스와는 길게 싸우지 마세요. 아트록스가 궁극기를 켜기 전 구간에서 (R)\'멈출 수 없는 맹공\'으로 한 번 크게 깎아 두면 켜진 뒤 회복으로 되돌아오는 폭이 줄어요. (P)\'영광스러운 죽음\' 상태에서도 공격이 대상 최대 체력에 비례한 추가 피해를 주니 쓰러지는 순간까지 아트록스를 때리세요.', item: '아트록스는 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기고, 평타 교환이 많아지면 가시 갑옷으로 이어가 상처를 걸어 두세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 아트록스의 회복을 눌러야 교환 이득이 유지돼요.' },
    '암베사': { lv1: '암베사는 (Q)\'교활한 휩쓸기\'로 반원을 휘두르며 피해를 주고, 스킬을 쓰는 동안 이동 명령을 내리면 (P)\'용사냥개의 발걸음\'으로 돌진하며 평타를 강화하는 공격적인 근접 챔피언이에요. 스킬 뒤 짧은 돌진으로 순식간에 붙으니 암베사가 닿기 전에 (E)\'학살자의 포효\'로 방어력을 깎아 두세요. (W)\'배척\' 보호막이 켜진 동안은 피해를 막고 강하게 내리치니 그 시간에는 공격을 아끼세요.', lv3: '(E)\'찢어 가르기\'는 주변에 피해를 주고 둔화시키니 암베사가 붙은 순간 (W)\'영혼의 용광로\' 보호막을 켜서 버티세요. (W)\'배척\'으로 준비하는 동안 미니언이 아닌 대상에게서 피해를 막았다면 내리치는 피해가 늘어나니 준비 중에 때리지 말고 끝난 뒤에 (Q)\'대량 학살 강타\'를 충전해 기절을 맞히세요. 스킬을 쓴 뒤 곧바로 이어지는 평타를 조심하세요.', lv6: '(R)\'공개 처형\'은 선택한 일직선상에서 가장 멀리 있는 적 챔피언에게 순간이동해 제압하니 정화나 점멸로는 풀 수 없고 제압 중에는 스킬과 평타도 못 써요. 정글러와 일직선으로 서 있으면 가장 먼 쪽이 걸리니 위치 선정을 신경 쓰세요. 암베사가 스킬을 연달아 써서 (P)\'용사냥개의 발걸음\' 돌진이 끝난 뒤라면 다음 스킬이 돌아오기 전에 (R)\'멈출 수 없는 맹공\'으로 선공하세요.', item: '암베사는 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기고, 제압을 풀 수 있는 수은 장식띠를 두 번째로 고려하세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 암베사가 돌진과 보호막으로 교환 이득을 노리니 점화로 마무리 피해를 확보하세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 얼음 구체를 날리고 폭발 시 반경 안의 적을 기절시키는 원거리 견제형이에요. 구체가 날아오는 길에서 옆으로 크게 비켜서야 폭발 범위에서도 벗어날 수 있어요. 구체가 터진 뒤 애니비아가 다음 스킬을 준비하는 틈에 (E)\'학살자의 포효\'로 방어력을 깎으며 붙으세요.', lv3: '(W)\'결정화\'는 지나갈 수 없는 얼음 벽을 만들어 접근을 막으니 벽이 녹을 때까지 억지로 돌아가지 마세요. (E)\'동상\'은 최근 냉기 폭발에 맞은 대상에게 피해가 두 배가 되니 구체에 맞은 직후에는 붙어서 교환하지 말고 빠지세요. 애니비아가 (Q)\'냉기 폭발\'과 (W)\'결정화\'를 쓰고 난 뒤에 (Q)\'대량 학살 강타\'를 충전해 기절을 맞히세요.', lv6: '(R)\'얼음 폭풍\'은 피해를 주고 이동 속도를 늦추니 폭풍 안에서는 싸우지 말고 범위 밖으로 빠지세요. 애니비아가 알이 되었다가 (P)\'환생\'으로 체력을 되찾는 점을 기억하고 처치한 뒤에도 방심하지 마세요. (W)\'결정화\' 벽이 길을 막고 있을 때는 벽 쪽으로 들어가지 말고 벽이 녹은 뒤나 벽이 없는 쪽에서 (R)\'멈출 수 없는 맹공\'으로 붙으세요.', item: '애니비아는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 헤르메스의 발걸음으로 (Q)\'냉기 폭발\'에 걸리는 기절 시간을 줄이세요.', spell: '점멸과 순간이동을 추천해요. 애니비아가 원거리에서 견제만 하는 라인에서는 순간이동으로 안전하게 귀환할 수 있어요.' },
    '야스오': { lv1: '야스오는 움직일 때마다 (P)\'낭인의 길\' 보호막이 차서 첫 교환에서 피해를 한 번 막아내요. 평타로 보호막을 먼저 터뜨린 뒤 교환을 시작하고, 야스오가 (E)\'질풍검\'으로 미니언을 타고 들어올 때는 미니언이 적은 쪽으로 위치를 잡으세요. (Q)\'강철 폭풍\'이 두 번 쌓이면 회오리가 날아와 띄우니 그때는 직선 위에 서지 마세요.', lv3: '(W)\'바람 장막\'은 모든 적의 투사체를 막으니 충격파를 발사하는 (E)\'학살자의 포효\'는 장막이 막을 수 있다고 보고 장막이 걷힌 뒤에 쓰세요. (E)\'질풍검\'으로 빠져나가는 야스오를 쫓지 말고, 돌진이 끝나는 위치를 예상해 (Q)\'대량 학살 강타\'를 충전하세요. 회오리가 준비된 야스오와는 회오리를 먼저 피한 뒤에 들어가세요.', lv6: '(R)\'최후의 숨결\'은 공중에 뜬 적에게만 쓸 수 있으니 상대 정글러나 회오리에 띄워지지 않도록 군중 제어를 조심하세요. 상대 정글러의 띄우기 스킬에 맞으면 야스오가 바로 궁극기로 이어 붙잡아 두니 상대 정글러가 근처에 있을 때는 라인을 너무 당기지 마세요. 이번 패치에서 (Q)\'강철 폭풍\' 피해가 조금 줄었어도 회오리 연계는 그대로니 야스오가 (E)\'질풍검\'과 (W)\'바람 장막\'을 쓴 직후에 (R)\'멈출 수 없는 맹공\'으로 붙어 마무리하세요.', item: '야스오는 물리 피해와 치명타가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 방어력과 평타 피해 감소를 주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 야스오가 보호막과 (E)\'질풍검\'으로 빠지기 쉬우니 점화로 마무리 피해를 확보하세요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 늘어난 평타를 넣고 맞은 대상의 방어력을 낮추는 근접 교환형이에요. 오공이 다가오며 Q를 쓸 때 (E)\'학살자의 포효\'를 먼저 맞히고 평타 사거리가 닿기 전에 거리를 조절하세요. 오공은 싸울수록 (P)\'바위 피부\'로 방어력이 올라가니 교환은 짧게 끊으세요.', lv3: '(W)\'분신 전사\'는 투명 상태로 돌진하고 분신이 근처 적을 때리니 오공이 사라지면 남은 분신이 아니라 본체가 돌진한 방향을 읽으세요. (E)\'근두운 급습\'은 대상에게 돌격해 분신 공격을 얹으니 오공의 E가 남아 있을 때는 (Q)\'대량 학살 강타\' 충전을 서서 하지 말고 거리를 지키세요. 오공이 E를 빼면 붙어서 (W)\'영혼의 용광로\' 보호막을 켜고 교환하세요.', lv6: '(R)\'회전격\'은 빙빙 휘두르며 이동 속도를 올리고 맞은 적을 띄우니 오공이 궁극기를 쓰는 순간 범위 밖으로 비켜서세요. 오공의 (W)\'분신 전사\'와 (E)\'근두운 급습\'이 빠진 틈에 (R)\'멈출 수 없는 맹공\'으로 달려들어 띄우고 끝내세요. 체력이 낮은 오공은 투명과 분신으로 빠지니 정글러와 함께 도주로를 막으세요.', item: '오공은 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 오공이 라인에서 오래 버티는 만큼 순간이동으로 교전 합류 가치가 커요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 쏘고 재사용으로 불러들여 경로상의 적에게 피해를 주는 원거리 견제형이에요. 저주가 되돌아오는 경로 위에 서 있지 않도록 옆으로 비켜서 두 번 맞는 일을 피하세요. 오로라가 (P)\'영혼 방호술\'로 제령한 영혼으로 체력을 회복하니 길게 소모전을 하지 마세요.', lv3: '(E)\'마법의 문\'은 영혼 마법을 발사해 피해와 둔화를 주고 안전한 뒤쪽으로 뛰어 물러나니 E를 쓴 오로라를 억지로 쫓지 마세요. (W)\'장막 너머로\'는 뛰어올라 착지하면 투명해지고 이동 속도가 올라가니 착지 지점을 읽고 (Q)\'대량 학살 강타\'를 충전하세요. 오로라가 W를 빼면 도주 수단이 줄어드니 그때 붙으세요.', lv6: '(R)\'세계의 경계\'는 도약해 충격파로 둔화를 걸고 영역을 만들어 이동 수단을 주니 영역 안에서는 싸우지 마세요. 오로라의 (W)\'장막 너머로\'가 빠진 틈에 (R)\'멈출 수 없는 맹공\'으로 달려들어 도주 수단이 없는 오로라를 띄우세요. 투명 상태의 오로라를 만나면 보이지 않아도 범위 스킬은 맞으니 (W)\'영혼의 용광로\' 재시전을 활용하세요.', item: '오로라는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기고, 불사르기로 붙어 있는 동안 피해를 보태세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 오로라가 원거리에서 견제하는 구도라 순간이동으로 귀환 후 라인에 복귀하세요.' },
    '오른': { lv1: '오른은 (Q)\'용암 균열\'로 둔화 지대를 만들어 견제하고 (P)\'간이 대장간\'으로 방어력과 마법 저항력이 높은 탱커형이에요. 균열의 목표 지점에는 잠시 후 용암 기둥이 생기니 그 자리에서 비켜서세요. 오른은 단단해서 교환이 잘 남지 않으니 막타 우선으로 웨이브를 정리하세요.', lv3: '(E)\'화염 돌진\'으로 지형에 부딪히면 충격파로 띄워 올리니 벽 가까이에서 오른과 맞서지 마세요. (W)\'불꽃 풀무질\'의 마지막 불꽃에 맞으면 불안정 상태가 되니 거리를 두고 오른의 W가 빠진 뒤에 (Q)\'대량 학살 강타\'를 충전해 붙으세요. 오른이 (Q)\'용암 균열\'을 쓰기 전에 짧게 교환하고 빠지는 쪽이 안전해요.', lv6: '(R)\'대장장이 신의 부름\'은 불의 정령이 오른에게 다가오며 지나간 적을 둔화시키고 불안정 상태로 만들며, 재시전으로 방향이 바뀌면 부딪힌 적을 띄워 올려요. 정령이 오는 직선 위에서 벗어나고 오른이 돌진해 오는 방향도 같이 읽으세요. 정령이 다가오는 동안 (R)\'멈출 수 없는 맹공\'으로 오른을 띄우면 공중에 뜬 동안은 재시전을 쓸 수 없지만, 풀린 뒤에는 다시 쓸 수 있으니 정령이 오는 직선에서도 함께 벗어나세요.', item: '오른은 방어력과 마법 저항력이 높아 오래 싸우니 강철심장으로 체력을 쌓고 근처에 머무는 오른에게 최대 체력 비례 추가 피해를 주세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 오른은 라인에서 끝내기 어려우니 순간이동으로 팀 교전에 합류하는 가치가 커요.' },
    '올라프': { lv1: '올라프는 (Q)\'역류\'로 도끼를 던져 방어력과 이동 속도를 낮추고, 잃은 체력에 비례해 공격 속도와 생명력 흡수를 얻는 (P)\'광전사의 분노\'로 체력이 낮을수록 위험해져요. 도끼를 던지는 직선과 도끼가 떨어지는 자리를 읽고 피해서 올라프가 도끼를 주우러 가는 사이 압박하세요. 올라프의 체력이 낮아 보여도 마지막 한 방까지 방심하지 마세요.', lv3: '(E)\'무모한 강타\'는 올라프 자신도 체력을 소모하는 스킬이니 서로 고정 피해를 맞교환하지 말고 (W)\'영혼의 용광로\' 보호막을 켜고 받아내세요. (W)\'버티기\'로 공격 속도와 보호막을 얻은 올라프에게는 평타를 길게 맞추지 말고 지속이 끝날 때까지 한 발 물러서세요. 올라프가 도끼를 던지고 주우러 가기 전에는 (Q)\'역류\'가 비니 그때 (Q)\'대량 학살 강타\'를 충전해 기절을 노리세요.', lv6: '(R)\'라그나로크\'가 켜진 올라프는 이동 방해 효과에 면역이라 그동안 기절이나 띄우기를 노리지 말고 거리를 벌려 지속이 끝나길 기다리세요. 올라프의 체력이 높아 공격 속도가 낮은 구간에 (R)\'멈출 수 없는 맹공\'으로 먼저 열면 올라프가 가장 약한 구간에서 싸울 수 있어요. 체력이 낮아진 올라프는 공격 속도와 생명력 흡수가 올라 평타 교환이 위험하니 마지막 한 방을 확실하게 노릴 때만 붙으세요.', item: '올라프는 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 올라프의 생명력 흡수가 커질수록 점화의 치유 감소가 중요해져요.' },
    '요네': { lv1: '요네는 두 번째 평타마다 마법 피해가 들어가고 치명타 확률이 올라가는 평타형 근접 챔피언이에요. (Q)\'필멸의 검\'이 두 번 쌓이면 돌진하며 돌풍으로 띄우니 직선을 피해 서고 평타 교환은 짧게 끊으세요. 요네가 (Q)\'필멸의 검\'을 찌르고 난 직후에 (E)\'학살자의 포효\'를 맞혀 방어력을 깎은 채로 교환하세요.', lv3: '(W)\'영혼 가르기\'로 요네가 보호막을 얻기 전에 거리를 좁히고, 보호막이 켜진 직후에는 교환을 멈추세요. (E)\'영혼해방\'은 영혼이 몸을 떠나 이동 속도가 늘고 끝나면 몸으로 돌아오며 입힌 피해를 다시 입히니 요네의 영혼이 돌아오는 구간을 읽고 피해를 줄이세요. 요네가 E를 쓰는 동안은 (Q)\'대량 학살 강타\'를 충전해 몸이 남은 위치를 노려 기절을 맞히세요.', lv6: '(R)\'운명봉인\'은 요네가 경로상의 마지막 챔피언 뒤로 이동하며 맞은 적을 끌어당기니 정글러와 일직선으로 서 있지 마세요. 요네가 (W)\'영혼 가르기\' 보호막을 이미 쓴 뒤에 (R)\'멈출 수 없는 맹공\'으로 시작하면 보호막 없이 맞출 수 있어요. 체력이 낮은 요네는 (E)\'영혼해방\'이 끝나면 몸이 있던 자리로 돌아오니 그 위치에 맞춰 마무리하세요.', item: '요네는 물리 피해와 치명타가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 요네가 (W)\'영혼 가르기\' 보호막을 두르고 버티거나 (E)\'영혼해방\'으로 몸 쪽으로 물러날 때 점화로 마무리 피해를 확보하세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 다음 평타에 추가 피해와 회복을 얻고 챔피언이나 처치한 대상에게서 무덤을 만들어요. 요릭이 평타로 막타를 치려는 순간 (E)\'학살자의 포효\'로 방어력을 깎으며 압박하세요. 요릭의 (P)\'영혼의 길잡이\' 안개 망령이 근처 적을 공격하니 망령이 소환된 구역에서는 교환을 피하세요.', lv3: '(W)\'망자의 진\'은 대상 지점에 벽을 세워 이동을 막지만 공격을 받으면 파괴되니 벽에 갇혔다면 평타로 부수고 빠져나오세요. (E)\'애도의 안개\'는 방어력을 낮추고 둔화를 거니 안개를 맞은 뒤에는 표식을 따라 오는 유닛을 조심하세요. 요릭이 W를 쓴 뒤에 (Q)\'대량 학살 강타\'를 충전해 붙으세요.', lv6: '(R)\'군도의 장송곡\'은 안개 마녀가 표적을 쫓고 죽은 적을 안개 망령으로 되살리니 군중 속에서 오래 싸우지 마세요. 안개 마녀가 나오면 요릭이 마녀의 표적을 때릴 때 추가 피해가 들어가니 마녀가 소환되기 전이나 마녀를 정리한 뒤에 (R)\'멈출 수 없는 맹공\'으로 붙으세요. (P)\'영혼의 길잡이\' 망령이 많을 때는 (W)\'영혼의 용광로\' 재시전으로 망령까지 함께 정리하며 교환하세요.', item: '요릭은 평타와 소환물로 싸우니 가시 갑옷이 어울리지만 첫 코어는 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'최후의 의식\' 회복을 눌러야 교환이 이어져요.' },
    '우디르': { lv1: '우디르는 (Q)\'야생 발톱\'이나 (W)\'강철 갑옷\' 같은 태세를 바꿔 가며 평타를 강화하고 (P)\'가교\'로 스킬 후 평타 공격 속도를 올려요. (E)\'불길 쇄도\' 태세는 이동 속도를 올리고 첫 평타에 기절을 주니 우디르가 E를 켜고 다가오면 평타를 맞기 전에 거리를 두고, 기절이 빠진 뒤에 (E)\'학살자의 포효\'로 방어력을 깎으며 교환하세요.', lv3: '(W)\'강철 갑옷\'은 보호막과 회복을 얻으니 우디르가 W를 켠 직후에는 교환을 멈추세요. 우디르가 (E)\'불길 쇄도\'를 쓴 뒤 재사용하면 이동 불가 효과에 면역이 되니 그 동안은 기절을 노리지 마세요. 재사용 효과가 끝나고 (E)\'불길 쇄도\'가 빠진 틈에 (Q)\'대량 학살 강타\'를 충전해 기절을 맞히세요.', lv6: '(R)\'날개 돋친 폭풍\'은 둔화를 걸고 재사용하면 적을 쫓는 폭풍을 풀어놓으니 폭풍 안에서는 싸우지 마세요. 우디르가 (E)\'불길 쇄도\' 재사용 효과를 다 쓰고 난 틈에 (R)\'멈출 수 없는 맹공\'으로 달려들어 띄우세요. 우디르가 태세를 하나씩 쓸 때마다 다음 평타 두 번의 공격 속도가 올라가니 어떤 태세가 빠졌는지 세어 보고 교환 시점을 정하세요.', item: '우디르는 물리와 마법 피해를 섞어 쓰고 보호막으로 버티니 강철심장으로 체력을 쌓고 근처에 머무는 우디르에게 추가 피해를 주세요. (E)\'불길 쇄도\' 기절을 받아내도록 신발은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 우디르의 보호막 회복을 눌러 교환 이득을 지키세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸고 기본 공격과 (W)\'심판의 원\'으로 다리에서 불꽃을 쏘는 원거리 견제형이에요. 폭약이 날아오는 선에서 옆으로 비켜서고 우르곳이 뒤로 물러서는 사이에 (E)\'학살자의 포효\'를 던지세요. (P)\'화염의 메아리\'는 평타와 (W)\'심판의 원\'에 다리 불꽃 피해를 더하니 우르곳 근처에서 길게 교환하지 마세요.', lv3: '(E)\'경멸\'은 돌진하며 보호막을 얻고 적 챔피언과 부딪히면 멈춰서 자신의 뒤로 던지니 우르곳의 E가 남아 있을 때는 정면에서 마주 서지 마세요. 우르곳이 (E)\'경멸\'을 빗맞혀 돌진이 끝난 자리를 읽고 (Q)\'대량 학살 강타\' 충전을 그 위치에 맞춰 두세요. (W)\'심판의 원\'은 최근 다른 스킬에 맞은 챔피언을 우선 공격하니 폭약을 맞은 뒤에는 원 범위에서 벗어나세요.', lv6: '(R)\'불사의 공포\'는 섬광탄이 처음 맞은 챔피언에게 꽂히고 체력이 낮아지면 처형할 수 있으니 체력이 낮을 때는 우르곳 사거리 안에 남지 마세요. 우르곳의 섬광탄이 빠진 시간에는 (R)\'멈출 수 없는 맹공\'으로 달려들어 띄워도 처형 걱정이 줄어요. 우르곳이 체력이 낮은 나를 끝내려고 붙으면 (P)\'영광스러운 죽음\'으로 잠시 되살아나 반격할 수 있어요.', item: '우르곳은 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 우르곳이 원거리 견제를 하는 라인이라 순간이동으로 안전하게 귀환해 체력을 채우세요.' },
    '워윅': { lv1: '워윅은 평타에 마법 피해가 붙고 체력이 낮아지면 (P)\'끝없는 허기\'로 추가 피해만큼 회복해서 접전이 길어질수록 위험해요. (Q)\'야수의 송곳니\'는 대상을 물어 최대 체력 비례 피해를 주고 그만큼 회복하니 워윅의 Q가 준비된 동안은 체력 교환을 길게 하지 마세요. 워윅이 체력이 낮아지면 (W)\'피의 사냥\' 효과가 커지니 서로 체력을 깎는 구도를 피하세요.', lv3: '(E)\'원시의 포효\'는 피해 감소를 얻고 끝나면 근처 적을 도망치게 만드니 워윅이 E를 켠 동안에는 무리하게 때리지 마세요. 포효에 걸려 도망치는 동안은 스킬을 쓸 수 없으니 E를 켠 워윅에게서 미리 거리를 벌려 두고, E가 빠진 뒤에 (Q)\'대량 학살 강타\'를 충전하세요. 워윅의 (W)\'피의 사냥\'은 체력이 낮은 적을 감지해 속도를 올려 주니 체력을 높게 유지하세요.', lv6: '(R)\'무한의 구속\'은 도약해 처음 부딪힌 챔피언을 제압하고 정화나 점멸로 풀 수 없으며 제압 중에는 스킬과 평타도 못 써요. 워윅의 이동 속도가 높을수록 도약 거리가 길어지니 정글러와 함께 서 있을 때 위치를 신경 쓰세요. 워윅이 (R)\'무한의 구속\'을 빗맞힌 직후에는 궁극기가 비니 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우세요.', item: '워윅은 마법 피해가 섞인 평타와 제압으로 싸우니 강철심장으로 체력을 쌓고 제압을 풀 수 있는 수은 장식띠를 두 번째로 고려하세요. 신발은 공포 지속시간을 줄여 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 회복을 눌러야 체력이 낮은 워윅을 끊을 수 있어요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 돌진하며 체력을 회복하고, 표식이 있거나 처치하면 재사용 대기시간이 초기화되는 연속 돌진형이에요. 표식이 없는 대상에게는 돌진이 이어지지 않으니 이렐리아가 미니언을 밟고 올 때 (E)\'학살자의 포효\'로 미니언을 밀어 방어력을 깎으세요. (W)\'저항의 춤\'을 충전하는 동안 받는 물리 피해가 줄어드니 그 시간에는 압박하지 마세요.', lv3: '(E)\'쌍검협무\'는 칼날이 서로를 향해 날아가며 맞은 적을 기절시키니 이렐리아가 E를 던진 방향을 읽고 비켜서세요. (E)\'쌍검협무\'가 빠진 이렐리아는 기절 연계가 끊기니 그때 (Q)\'대량 학살 강타\'를 충전하며 붙으세요. (P)\'아이오니아의 열정\' 중첩이 쌓이면 공격 속도가 올라가니 평타 교환이 길어지지 않게 끊으세요.', lv6: '(R)\'선봉진격검\'은 적 챔피언에게 맞으면 칼날이 펼쳐져 결계를 만들고 통과하면 둔화되니 결계 안에서 도망치지 말고 이렐리아에게 붙어 싸우세요. 이렐리아가 (Q)\'칼날 쇄도\'를 쓴 직후에 (R)\'멈출 수 없는 맹공\'으로 달려들어 띄우면 공중에 뜬 동안은 다음 돌진을 쓸 수 없어요. 체력이 낮은 이렐리아는 (Q)\'칼날 쇄도\'로 빠지니 미니언을 먼저 정리하세요.', item: '이렐리아는 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기고, 평타 교환이 많아지면 가시 갑옷으로 이어가세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 이렐리아의 (Q)\'칼날 쇄도\' 회복과 연속 돌진에 대응하려면 점화로 마무리 피해를 확보하세요.' },
    '일라오이': { lv1: '일라오이는 (Q)\'촉수 강타\'로 촉수를 내리쳐 물리 피해를 주고 (W)\'혹독한 가르침\'으로 대상에게 도약해요. 일라오이의 촉수는 근처의 통과할 수 없는 지형에 솟아 영혼과 숙주를 공격하니 일라오이 쪽 지형 근처에서는 오래 싸우지 마세요. 일라오이가 W로 도약한 직후에 (E)\'학살자의 포효\'를 맞히세요.', lv3: '(E)\'영혼의 시험\'을 맞으면 내 영혼이 분리되고 일라오이가 그 영혼을 때리면 피해 일부가 나에게 돌아와요. 영혼에서 멀어지면 내가 숙주가 되어 촉수가 나를 공격하니 영혼에서 너무 멀리 떨어지지 마세요. 일라오이가 E를 빼면 (Q)\'대량 학살 강타\'를 충전해 기절을 맞히세요.', lv6: '(R)\'믿음의 도약\'은 근처 적에게 물리 피해를 주고 맞은 챔피언마다 촉수가 소환되니 일라오이의 촉수 쪽에서 교환하지 마세요. 촉수가 솟은 지형이 아닌 반대편에서 (R)\'멈출 수 없는 맹공\'을 돌진시켜 촉수가 없는 곳에서 띄우세요. 일라오이는 체력이 높으니 정글러가 오기 전에 포탑 압박으로 시간을 쓰세요.', item: '일라오이는 물리 피해가 중심이고 오래 싸우니 강철심장으로 체력을 쌓고 근처에 머무는 일라오이에게 최대 체력 비례 추가 피해를 주세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 일라오이는 라인에서 오래 버티니 순간이동으로 합류하는 가치가 커요.' },
    '자크': { lv1: '자크는 (Q)\'탄성 주먹\'으로 적을 붙잡고 다른 적을 공격하면 서로 부딪히게 하며, 스킬을 맞힐 때마다 (P)\'세포 분열\'로 조각이 떨어져 나가요. 조각을 자크가 다시 흡수하면 체력을 회복하니 조각이 널린 자리에서 교환을 길게 끌지 마세요. 자크의 (W)\'불안정 물질\'은 최대 체력 비례 마법 피해라 체력이 높은 사이온이 오래 맞으면 크게 깎여요.', lv3: '(E)\'새총 발사\'는 전방으로 몸을 날리는 돌진이라 자크가 E로 붙을 때 착지 지점에서 (Q)\'대량 학살 강타\'를 충전해 기절을 노리세요. (W)\'불안정 물질\'이 터지는 순간은 폭발 범위 밖으로 비켜서세요. 자크가 E를 빼면 도망갈 수단이 줄어드니 그때 압박하세요.', lv6: '(R)\'바운스!\'는 네 번 튀며 맞은 적을 띄우고 둔화시키니 자크가 궁극기를 쓰는 걸 보면 착지 범위에서 벗어나세요. (P)\'세포 분열\'이 준비된 자크는 치명상을 입으면 네 조각으로 갈라졌다가 합쳐지려 모이니 조각이 남아 있으면 처치가 끝난 게 아니에요. 자크의 (Q)\'탄성 주먹\'이 빠진 뒤에 (R)\'멈출 수 없는 맹공\'으로 시작하면 붙잡혀 던져질 위험이 줄어요.', item: '자크는 마법 피해가 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 자크가 조각을 흡수하며 회복하는 시간을 줄이세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 다음 평타를 두 번 때리고 체력을 회복하며, 적 챔피언을 맞힐 때마다 (P)\'전쟁 단련\' 결심이 쌓여요. 결심이 쌓일수록 추가 공격력이 늘어나니 평타 교환을 짧게 끊고 한 번에 크게 맞는 구도를 피하세요. 자헨이 Q를 쓴 직후에 (E)\'학살자의 포효\'로 방어력을 깎으세요.', lv3: '(W)\'공포의 귀환\'은 지정한 방향으로 내질러 맞은 적을 끌어당기니 자헨의 W가 남아 있을 때는 직선 위에 서지 마세요. (E)\'찬란한 쇄도\'로 돌진하고 주변을 가르니 자헨이 E를 쓴 위치에 맞춰 (Q)\'대량 학살 강타\'를 충전하세요. 자헨이 스킬을 빼고 나면 도망갈 수단이 부족하니 그때 붙으세요.', lv6: '(R)\'단호한 판결\'은 날아올라 내려찍으며 입힌 피해의 일부를 회복하니 자헨이 궁극기를 쓰는 걸 보면 범위 밖으로 비켜서세요. (P)\'전쟁 단련\' 결심이 가득 차면 부활할 수 있으니 처치한 뒤에도 방심하지 마세요. 자헨이 (E)\'찬란한 쇄도\'로 빠진 뒤라면 (R)\'멈출 수 없는 맹공\'의 긴 돌진으로 따라붙어 띄우세요.', item: '자헨은 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 자헨의 회복을 눌러야 체력이 낮은 자헨을 끊을 수 있어요.' },
    '잭스': { lv1: '잭스는 (Q)\'도약 공격\'으로 지정한 유닛에게 뛰어올라 내려치고, 연속으로 평타를 치면 (P)\'가차없는 맹공\'으로 공격 속도가 올라가는 근접 챔피언이에요. 잭스가 뛰어들 수 있는 미니언이나 챔피언이 있는지 보고 웨이브를 정리해 도약 대상을 없애세요. 잭스가 W로 평타를 강화하면 한 발 물러나 평타 교환을 끊으세요.', lv3: '(E)\'반격\'은 잠깐 동안 적의 공격을 모두 피한 뒤 주변 적을 기절시키니 잭스가 E를 켠 동안은 평타를 낭비하지 말고 끝나는 순간 범위 밖으로 비켜서세요. (E)\'반격\'이 끝난 직후가 잭스를 상대로 (Q)\'대량 학살 강타\'를 충전하기 좋은 시간이에요. (W)\'영혼의 용광로\' 보호막은 잭스의 연속 평타가 쌓이기 전에 켜세요.', lv6: '(R)\'무기의 달인\'은 세 번째 연속 공격마다 마법 피해를 주고 방어력과 마법 저항력을 올리니 잭스가 궁극기를 켠 동안은 교환을 길게 끌지 마세요. (E)\'반격\'이 켜진 잭스에게 붙으면 효과가 끝날 때 기절을 맞기 쉬우니 (R)\'멈출 수 없는 맹공\'은 (E)\'반격\'이 빠진 뒤에 쓰는 편이 좋아요. 체력이 낮은 잭스는 (Q)\'도약 공격\'으로 빠지니 미니언이 없는 쪽에서 붙으세요.', item: '잭스는 물리 피해와 마법 피해를 섞어 쓰고 평타가 중심이라 강철심장으로 체력을 쌓아 근처에 머무는 잭스에게 최대 체력 비례 추가 피해를 주세요. (E)\'반격\' 기절에 걸릴 때를 대비해 신발은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 잭스가 도약으로 빠지기 전에 마무리 피해를 확보하세요.' },
    '제이스': { lv1: '제이스는 해머 쪽에서 (Q)\'하늘로!\'로 도약해 이동 속도를 낮추고 (E)\'천둥 강타\'로 뒤로 밀쳐내며, 캐논 쪽에서는 (Q)\'전격 폭발\'로 멀리서 견제해요. 캐논 형태의 전기 구체가 날아오는 직선 위에 서지 말고 옆으로 비켜서세요. 제이스가 (Q)\'전격 폭발\'을 쓴 직후가 거리를 좁히기 좋은 시간이에요.', lv3: '(E)\'천둥 강타\'에 밀쳐지면 거리가 벌어지니 제이스가 E를 쓴 직후에 다시 붙어 (E)\'학살자의 포효\'로 방어력을 깎으세요. 제이스가 사거리 긴 형태로 견제하면 억지로 쫓지 말고 웨이브를 정리해 막타를 챙기세요. 제이스가 (Q)\'하늘로!\'로 뛰어든 착지점에 (Q)\'대량 학살 강타\'를 충전해 기절을 노리세요.', lv6: '(R)\'머큐리 캐논\'으로 변환하면 사거리가 늘고 방어력과 마법 저항력을 깎는 첫 공격을 노리니 변환 직후의 교환을 피하세요. 제이스가 캐논 형태로 견제한 뒤 스킬이 빠진 틈에 (R)\'멈출 수 없는 맹공\'으로 붙어 띄우세요. 캐논 쪽 가속 관문 연계는 아군에게 이동 속도를 줘 정글러가 합류하기 쉬우니 정글 시야를 확인하세요.', item: '제이스는 물리 피해 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 캐논 형태 평타 견제를 덜 아프게 받는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 제이스가 사거리로 견제하는 구도라 순간이동으로 귀환 후 라인에 복귀하세요.' },
    '초가스': { lv1: '초가스는 (Q)\'파열\'로 지정한 지역의 적을 띄워 올리고 둔화시키며, 유닛을 죽일 때마다 (P)\'육식\'으로 체력과 마나를 회복해요. (Q)\'파열\'은 잠시 후 땅이 솟는 스킬이라 맞기 전에 옆으로 움직여 피하고 띄워진 동안은 아무 스킬도 쓸 수 없다는 점을 기억하세요. 초가스의 (E)\'날카로운 가시\'는 평타마다 정면에 가시를 쏘고 둔화를 거니 초가스 정면 직선 위에서 평타 교환을 길게 하지 마세요.', lv3: '(W)\'흉포한 울부짖음\'은 원뿔 범위의 적을 침묵시키니 맞기 전에 (W)\'영혼의 용광로\' 보호막을 미리 켜 두세요. 초가스가 W를 쓴 직후에 (Q)\'대량 학살 강타\'를 충전해 붙으면 기절을 맞힐 수 있어요. 초가스가 (Q)\'파열\'을 빼면 나를 띄워 둔화시킬 수단이 줄어드니 그때 압박하세요.', lv6: '(R)\'포식\'은 방어력을 무시하는 큰 고정 피해를 주고 처치하면 초가스가 커지니 체력이 낮은 채 초가스 근처에 남지 마세요. 초가스의 (Q)\'파열\'이 남아 있으면 붙은 뒤 띄워져 (R)\'포식\'까지 이어 맞기 쉬우니 (R)\'멈출 수 없는 맹공\'은 (Q)\'파열\'이 빠진 뒤에 쓰세요. 초가스는 막타를 먹으며 성장하니 웨이브를 놓칠 상황이면 순간이동으로 라인을 챙기세요.', item: '초가스는 마법 피해가 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 (W)\'흉포한 울부짖음\' 침묵 시간을 줄여 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 초가스가 막타로 성장을 노리는 라인이라 순간이동으로 웨이브 손실을 줄이세요.' },
    '카밀': { lv1: '카밀은 (Q)\'정확성 프로토콜\'로 다음 평타를 강화하고 이동 속도를 올려 붙으며, 챔피언을 평타로 때릴 때마다 (P)\'적응형 방어 체계\' 보호막을 얻어요. 보호막은 내가 가한 피해 유형에 맞춰 물리 또는 마법 하나만 생기니 평타 사이에 (E)\'학살자의 포효\'를 끼워 방어력을 깎으며 교환하세요. 카밀이 Q를 쓴 직후에는 평타 교환을 피하고 한 발 물러서세요.', lv3: '(W)\'전술적 휩쓸기\'는 원뿔 바깥쪽 절반에 맞은 적을 둔화시키고 추가 피해를 주니 안쪽으로 파고들어 피해를 줄이세요. (E)\'갈고리 발사\'는 벽으로 날아갔다가 착지하며 기절을 주니 벽이 가까운 위치에서는 카밀의 착지 지점에서 멀리 서세요. 카밀의 (E)\'갈고리 발사\'가 빠져 벽으로 빠지는 길이 막힌 시간에 (Q)\'대량 학살 강타\' 충전으로 기절을 노리세요.', lv6: '(R)\'마법공학 최후통첩\'은 대상에게 돌진해 일정 지역에 가두니 카밀이 궁극기를 쓰면 구역 안에서 피해를 맞추는 싸움이 돼요. 구역 안에서는 카밀이 평타로 붙어 있는 동안 (W)\'영혼의 용광로\' 재시전으로 주변 피해를 넣으세요. (E)\'갈고리 발사\'가 빠진 카밀은 벽을 타고 빠질 수단이 없으니 그때 (R)\'멈출 수 없는 맹공\'으로 선공하세요.', item: '카밀은 물리 피해 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 카밀의 회복과 보호막으로 교환이 길어지니 점화로 마무리 피해를 확보하세요.' },
    '카사딘': { lv1: '1~2레벨에는 (Q)\'대량 학살 강타\'를 사용해 카사딘의 움직임을 제약하며 라인 주도권을 가져가세요. 카사딘의 (Q)\'무의 구체\'로 인한 보호막이 없을 때를 노려 딜교환을 하는 것이 좋아요. 미니언을 먹으러 오는 타이밍에 맞춰 거리 조절을 철저히 하세요.', lv3: '3레벨 이후에는 (Q)\'대량 학살 강타\'를 충분히 충전해 적을 기절시킨 뒤 (W)\'영혼의 용광로\'를 폭발시키세요. 카사딘의 (E)\'힘의 파동\'은 정면 원뿔 범위에 둔화를 거니 맞은 뒤 무리하게 쫓지 말고 (E)\'학살자의 포효\'로 둔화를 되돌려 주세요. 상대의 스킬이 빠진 타이밍을 노려 딜교환을 이어가세요.', lv6: '6레벨 이후 카사딘이 (R)\'균열 이동\'으로 도망갈 수 있으므로 (R)\'멈출 수 없는 맹공\'을 신중하게 사용하세요. 상대의 폭발적인 피해에 주의하며 라인을 밀어넣고 정글러의 개입을 유도해야 해요. 카사딘은 (P)\'공허석\'으로 받는 마법 피해가 줄어드니 (W)\'영혼의 용광로\' 폭발보다 (Q)\'대량 학살 강타\'와 (R)\'멈출 수 없는 맹공\'의 물리 피해로 마무리하세요.', item: '헤르메스의 발걸음과 강철심장을 추천해요. 마법 피해를 줄이기 위해 헤르메스의 발걸음을 가고 체력을 높이기 위해 강철심장을 선택하세요.', spell: '점멸과 유체화를 추천해요. 카사딘을 추격할 때 유체화가 큰 도움이 돼요.' },
    '카시오페아': { lv1: '(Q)\'맹독 폭발\' 견제를 최대한 버티며 체력을 보존하세요. (E)\'학살자의 포효\'로 상대의 이동 속도를 늦춰 견제하고, 라인을 무리하게 밀지 말고 내 포탑 쪽에서 미니언을 받아먹으세요.', lv3: '(W)\'영혼의 용광로\' 보호막으로 (E)\'쌍독니\'의 누적 피해를 흡수하며 버티세요. (Q)\'대량 학살 강타\'를 충전해 압박을 주어 상대가 (W)\'독기의 늪\'을 미리 사용하게 유도하세요. (E)\'학살자의 포효\'로 둔화를 걸어 딜교환 각을 보세요.', lv6: '(W)\'독기의 늪\' 안에서는 이동 스킬을 쓸 수 없으니 늪 밖에서 (R)\'멈출 수 없는 맹공\'을 시작하세요. (R)\'석화의 응시\'를 사용할 때 등을 돌리면 기절 대신 둔화만 받아요. 돌진 후 (Q)\'대량 학살 강타\'로 연계하여 적을 기절시키고 킬각을 잡으세요.', item: '헤르메스의 발걸음과 케이닉 루컨을 추천해요. 마법 저항력을 높여 (E)\'쌍독니\' 피해를 줄이고 강인함으로 군중 제어 시간을 단축하세요.', spell: '점멸과 순간이동을 추천해요. (R)\'석화의 응시\'를 피하거나 빠르게 거리를 좁히기 위해 점멸이 필요하고, 라인 복귀를 위해 순간이동을 사용하세요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 날려 표식을 남기고, 스킬에 세 번 적중당하면 (P)\'폭풍의 표식\'이 기절을 만드는 원거리 챔피언이에요. 표창이 날아오는 직선에서 비켜서고 표식이 두 개 쌓였을 때는 한 발 물러서서 세 번째 적중을 피하세요. 케넨이 표창을 던지고 뒤로 물러서기 전에 (E)\'학살자의 포효\'를 맞혀 방어력을 깎은 채 평타를 섞으세요.', lv3: '(W)\'전류 방출\'은 평타를 몇 번 치면 힘이 충전되어 다음 평타에 표식을 남기니 케넨의 평타 횟수를 세어 충전 직전에는 교환을 끊으세요. (E)\'번개 질주\'로 유닛을 뚫고 지나가는 케넨은 쫓지 말고 E 직후에 (Q)\'대량 학살 강타\'를 충전해 기절을 노리세요. 케넨이 E를 빼면 붙어서 짧게 교환하고 빠지세요.', lv6: '(R)\'날카로운 소용돌이\'는 근처 적 챔피언을 공격해 마법 피해를 주니 케넨이 궁극기를 쓰면 범위 안에서 싸우지 마세요. 케넨이 (E)\'번개 질주\'로 빠진 뒤 도착한 지점을 노려 (R)\'멈출 수 없는 맹공\'의 긴 돌진으로 따라붙으세요. 나에게 (P)\'폭풍의 표식\'이 쌓여 있다면 (W)\'영혼의 용광로\' 재시전으로 주변 피해를 넣고 먼저 빠지세요.', item: '케넨은 마법 피해가 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 (P)\'폭풍의 표식\' 기절이 짧아지는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 케넨이 거리를 두고 견제하는 라인이라 순간이동으로 귀환 후 복귀하세요.' },
    '케일': { lv1: '케일은 (Q)\'광휘의 일격\'으로 이동 속도와 방어력, 마법 저항력을 낮추며 관통 견제를 하고, (P)\'거룩한 승천\'으로 레벨이 오를수록 강해져요. 초반에는 케일이 약한 시기이니 막타 경쟁을 이어가며 (E)\'학살자의 포효\'로 방어력을 깎아 압박하세요. 케일의 날개가 불타오르기 전에 주도권을 쥐고 교환을 이어가세요.', lv3: '(E)\'화염주문검\'은 다음 공격에 잃은 체력에 비례한 추가 피해를 주니 케일이 E를 켰을 때는 체력을 높게 유지한 채 교환하세요. (W)\'천상의 축복\'은 케일과 가까운 아군을 회복시키고 이동 속도를 올리니 케일이 W를 쓰면 한 템포 쉬세요. 케일의 (W)\'천상의 축복\'이 빠진 시간에 (Q)\'대량 학살 강타\' 기절을 맞히면 회복 없이 교환할 수 있어요.', lv6: '(R)\'신성한 심판\'은 아군 한 명을 무적으로 만들고 그 주변을 정화하니 케일이 궁극기를 쓰는 동안은 교환하지 말고 효과가 끝난 뒤에 붙으세요. 이번 패치에서 케일의 Q와 궁극기 재사용 대기시간이 줄어 (Q)\'광휘의 일격\' 견제와 (R)\'신성한 심판\'을 더 자주 보게 되니, 케일이 강해지기 전 라인전에서 성장 차이를 벌려 두세요. 케일의 (R)\'신성한 심판\'이 빠진 것을 확인한 뒤에 (R)\'멈출 수 없는 맹공\'으로 시작하세요.', item: '케일은 마법 피해 평타가 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기고 후반 위협에 대비하세요. 신발은 마법 저항력이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 케일이 후반에 강해지니 점화로 초반 교환 이득을 굳히세요.' },
    '코그모': { lv1: '코그모가 (Q)\'부식성 침\'을 사용하여 방어력을 낮추며 견제할 수 있어요. (W)\'영혼의 용광로\'를 사용해 보호막을 얻으며 미니언을 챙기며 버텨야 해요. 무리하게 다가가지 말고 거리 조절을 하며 차분하게 대응하세요.', lv3: '코그모가 (W)\'생체마법 폭격\'을 사용하면 사거리가 길어지니 주의하세요. (Q)\'대량 학살 강타\'를 길게 충전해서 코그모를 공중으로 띄우는 것이 중요해요. (E)\'공허의 분비물\'이 만든 둔화 지역을 피하며 접근하세요.', lv6: '(R)\'멈출 수 없는 맹공\'으로 돌진하여 코그모를 기절시키고 싸움을 시작해요. 코그모의 (R)\'살아있는 곡사포\'를 맞으며 체력이 너무 낮아지지 않게 조심하세요. 정글러와 함께 코그모를 압박하며 라인을 관리하세요.', item: '헤르메스의 발걸음과 강철심장을 추천해요. 코그모의 (W)\'생체마법 폭격\' 마법 피해에 저항하고 체력을 늘려 전투를 길게 이어가기 위해서예요.', spell: '점멸과 유체화를 추천해요. 유체화로 (E)\'공허의 분비물\' 둔화 지역을 지나 빠르게 접근하고 점멸로 마지막 거리를 좁혀요.' },
    '코르키': { lv1: '(Q)\'인광탄\'은 지정한 지역에 터지는 범위 스킬이라 미니언 뒤로 숨어도 막을 수 없어요. 폭탄이 떨어지는 위치를 보고 옆으로 움직이며 (W)\'영혼의 용광로\' 보호막으로 견제를 받아내세요. 첫 웨이브부터 무리하게 진입하면 피해가 크니 파밍에 집중하세요.', lv3: '(E)\'학살자의 포효\'를 맞춰 둔화를 걸고 (Q)\'대량 학살 강타\'를 충전해 진입하세요. 상대의 (W)\'발키리\'가 빠진 타이밍을 노려 딜교환을 시도하는 것이 좋아요. (E)\'개틀링 건\'의 방어력 감소 효과가 있으니 보호막 관리가 중요해요.', lv6: '(R)\'멈출 수 없는 맹공\'으로 돌진하여 상대의 (W)\'발키리\' 사용을 강제하세요. (R)\'미사일 폭격\' 중 마지막 공격의 피해가 매우 크니 체력 관리에 유의하세요. 정글러와 함께 좁은 길목에서 덮치면 킬을 내기 편해요.', item: '헤르메스의 발걸음과 끝없는 절망을 추천해요. 마법 피해를 줄이고 체력과 방어력을 높여 지속 전투 능력을 강화하기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 라인 복귀와 갑작스러운 진입을 위해 필요해요.' },
    '퀸': { lv1: '퀸은 (Q)\'실명 공격\'으로 시야를 크게 좁히고 (P)\'매사냥\' 표식 대상을 평타로 때리며 견제하는 원거리 챔피언이에요. (Q)\'실명 공격\'에 맞으면 시야가 크게 좁아지니 시야가 돌아올 때까지 무리하게 앞으로 나가지 말고 웨이브 정리에 집중하세요. 퀸이 막타를 치러 다가올 때 (E)\'학살자의 포효\'로 미니언을 밀어 뒤의 퀸에게 방어력 감소를 걸어 두세요.', lv3: '(E)\'공중제비\'는 적에게 돌진해 둔화를 준 뒤 최대 공격 사거리로 물러나 착지하니 맞은 직후 억지로 쫓지 말고 (W)\'영혼의 용광로\' 보호막으로 이어지는 평타를 받아내세요. 퀸이 미니언 사이에서 막타를 치러 가까이 머무를 때 (Q)\'대량 학살 강타\'를 충전해 기절을 노리세요. 퀸이 (P)\'매사냥\' 표식 대상을 때리면 (W)\'예리한 감각\'으로 공격 속도와 이동 속도가 오르니 표식이 붙은 순간에는 교환을 끊으세요.', lv6: '(R)\'후방 지원\'은 퀸과 발러가 빠르게 날아다니다가 종료하면 공중 강습으로 피해를 주니 퀸이 궁극기를 켜면 합류와 도주 신호로 읽고 라인에서 위치를 조심하세요. 퀸이 (R)\'후방 지원\'으로 날아다니는 동안은 쫓지 말고, 종료해 내려앉는 위치에 (R)\'멈출 수 없는 맹공\'의 긴 돌진으로 붙으세요. 퀸이 라인을 떠나 합류할 때를 노려 웨이브를 밀어 포탑을 압박하세요.', item: '퀸은 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 퀸이 합류와 견제를 반복하는 라인이라 순간이동으로 대응하기 좋아요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 짧은 직선의 적을 둔화시키고 두 번 쌓이면 적을 끌어당기는 충격파를 쏘는 탱커형이에요. (Q)\'엔토포 타격\'에 한 번 맞았다면 다음 적중이 끌어당김으로 이어지니 한 발 물러서서 두 번째 적중을 피하세요. 막타 경쟁이 중요한 구간에서는 (E)\'학살자의 포효\'로 방어력을 깎으며 압박하세요.', lv3: '(W)\'길을 여는 자\'는 충전하는 동안 받는 피해가 줄고 돌진이 시작되면 군중 제어로 막을 수 없으니 충전이 보이면 직선 밖으로 빠지세요. 충전 중인 크산테에게는 교환하지 말고 (W)\'영혼의 용광로\' 보호막을 켜 두세요. 크산테가 돌진을 끝내고 멈추는 지점에 맞춰 (Q)\'대량 학살 강타\' 충전을 준비해 두세요.', lv6: '(R)\'총공세\'는 적을 뒤로 밀어내며 벽을 뚫고 이후 방어력이 감소하는 대신 피해량과 체력 회복량이 늘어나니 켜진 크산테와는 길게 싸우지 마세요. 크산테가 (W)\'길을 여는 자\'를 쓰고 멈춘 틈에 (R)\'멈출 수 없는 맹공\'으로 달려들어 띄우세요. 크산테는 단단해 처치가 어려우니 정글러가 오기 전에는 라인을 밀어 압박하세요.', item: '크산테는 오래 싸우는 탱커라 강철심장으로 체력을 쌓고 근처에 머무는 크산테에게 최대 체력 비례 추가 피해를 주세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 크산테의 회복을 눌러야 총공세 이후에도 마무리가 돼요.' },
    '클레드': { lv1: '클레드는 스칼을 타고 있는 동안 스칼이 대신 피해를 받아 초반 교환이 질기고, (Q)\'덫날리기\'로 붙잡은 뒤 근거리를 유지하면 끌어당겨요. 덫에 붙잡히면 클레드와 거리를 벌려 끌려가는 일을 피하세요. 클레드의 (E)\'이랴!\'로 이동 속도가 올라가니 직선 방향을 보고 비켜서세요.', lv3: '스칼이 쓰러져 클레드가 내리면 스킬이 바뀌고 챔피언에 대한 피해가 줄어드니 스칼을 먼저 부수는 교환을 이어가세요. (W)\'버럭버럭\'은 네 번 연속 평타 속도를 엄청나게 올리니 클레드가 W를 켠 직후에는 한 발 물러서 평타 교환을 끊으세요. 덫이 빗나간 클레드는 한동안 끌어당길 수단이 없으니 그 틈에 (Q)\'대량 학살 강타\'로 기절을 노리세요.', lv6: '(R)\'돌겨어어억!!!\'은 클레드와 스칼이 보호막을 쓴 채 경로상의 첫 적 챔피언에게 돌격하니 정글러와 함께 서 있지 말고 경로 밖으로 비켜서세요. 스칼의 용기가 차서 클레드가 다시 올라타기 전에 (R)\'멈출 수 없는 맹공\'으로 붙어 띄워 끝내세요. 스칼이 쓰러져 클레드가 내린 상태라면 챔피언에 대한 피해가 줄어 있으니 그때 압박을 몰아치세요.', item: '클레드는 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 스칼이 사라진 클레드를 끊으세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 속도를 늦추고 체력을 회복하며 (P)\'절대 미각\' 중첩을 쌓는 탱커형 챔피언이에요. 중첩이 세 번 쌓이면 다음 혀 채찍이 기절이고 집어삼키기도 가능하니 같은 대상에게 오래 맞지 않도록 교환은 짧게 끊으세요. 탐 켄치가 Q를 쓴 직후에 (E)\'학살자의 포효\'를 맞혀 방어력을 깎으며 거리를 좁히세요.', lv3: '(W)\'심연 잠수\'는 아래로 잠수해 지정한 위치에 나타나며 주변 적을 띄우니 탐 켄치가 W를 쓰려는 방향을 읽고 비켜서세요. 띄워진 동안은 아무 스킬도 쓸 수 없으니 (W)\'영혼의 용광로\'는 미리 켜 두세요. 탐 켄치가 W를 빼면 (Q)\'대량 학살 강타\'를 충전해 기절을 노리세요.', lv6: '(R)\'집어삼키기\'는 중첩이 세 번 쌓인 적 챔피언을 삼키니 탐 켄치와 오래 싸우지 말고 중첩이 쌓이기 전에 빠지세요. 탐 켄치는 아군을 삼켜 보호막을 줄 수도 있으니 궁극기가 빠졌는지 확인하고 교환하세요. 중첩을 쌓기 전에 (R)\'멈출 수 없는 맹공\'으로 먼저 띄우면 탐 켄치도 그동안 스킬을 쓸 수 없어요.', item: '탐 켄치는 마법 피해와 기절 연계로 싸우니 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 헤르메스의 발걸음을 신어 (Q)\'혀 채찍\' 기절 시간을 줄이세요.', spell: '점멸과 순간이동을 추천해요. 탐 켄치가 라인에서 오래 버티니 순간이동으로 팀 교전에 합류하세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 둔화를 걸고 내 공격력을 흡수하며, 근처에서 유닛이 죽을 때마다 (P)\'헌납\'으로 체력을 회복해요. 트런들이 깨물기를 쓰면 내 평타 피해가 줄어드니 평타 교환을 길게 하지 말고 (E)\'학살자의 포효\'로 방어력을 깎으며 짧게 끊으세요. 미니언이 죽는 순간마다 트런들이 회복하니 웨이브가 부딪히는 곳 근처에서 교환하지 마세요.', lv3: '(E)\'얼음 기둥\'은 지나갈 수 없는 돌기둥을 만들고 주변 적의 이동 속도를 낮추니 기둥이 막은 쪽으로 돌지 말고 반대편에서 붙으세요. (W)\'얼음 왕국\' 안에서는 트런들의 공격 속도와 이동 속도가 오르고 치유도 늘어나니 왕국 안에서는 교환하지 마세요. 트런들이 기둥을 쓴 뒤에는 길을 막을 수단이 빠지니 그때 (Q)\'대량 학살 강타\'를 충전해 맞히세요.', lv6: '(R)\'진압\'은 대상에게서 체력과 방어력, 마법 저항력의 일정 비율을 훔치니 체력이 높은 사이온은 훔쳐 가는 양도 크다는 점을 기억하세요. 트런들이 궁극기를 쓴 뒤에는 능력치가 크게 오르니 교환을 피하고, 쓰기 전에 체력을 높게 유지한 채 (R)\'멈출 수 없는 맹공\'으로 먼저 시작하세요. (E)\'얼음 기둥\'이 길을 막고 있을 때는 기둥 쪽으로 들어가지 말고 열린 방향으로 붙으세요.', item: '트런들은 물리 피해 중심이라 태양불꽃 방패로 방어력과 체력을 챙겨 (Q)\'깨물기\'가 섞인 평타 교환을 버티세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 트런들의 회복을 눌러 체력 싸움에서 밀리지 마세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 평타마다 분노를 쌓고 (Q)\'피의 갈망\'으로 분노를 써서 체력을 회복하는 치명타형 근접 챔피언이에요. 체력이 낮을수록 공격력이 올라가니 트린다미어의 체력을 깎다가도 끝내지 못하면 반격을 맞을 수 있다는 점을 기억하세요. 분노가 쌓이기 전에 (E)\'학살자의 포효\'로 방어력을 깎으며 짧게 교환하세요.', lv3: '(W)\'조롱의 외침\'은 주변 챔피언의 공격력을 낮추고 등을 돌린 챔피언의 이동 속도를 낮추니 W를 맞은 뒤에는 등을 돌리고 도망치지 말고 맞서세요. 트린다미어가 (E)\'회전 베기\'로 붙을 때 (W)\'영혼의 용광로\' 보호막을 켜 두고 받아내세요. (Q)\'피의 갈망\'으로 분노를 쓰고 비워진 트린다미어는 치명타 확률이 낮아지니 그 틈에 기절을 맞히세요.', lv6: '(R)\'불사의 분노\'가 켜진 동안은 트린다미어가 죽을 수 없으니 스킬을 아끼고 지속이 끝난 뒤에 (R)\'멈출 수 없는 맹공\'으로 붙어 띄워 마무리하세요. 지속 중에 평타 교환을 하면 손해만 늘어나니 한 발 물러서 효과가 끝나길 기다리세요. 트린다미어가 체력이 낮을 때는 공격력이 올라가니 아슬하게 남은 상대에게 무작정 붙지 마세요.', item: '트린다미어는 치명타 평타 중심이라 태양불꽃 방패로 방어력과 체력을 챙기고, 평타 교환이 많아지면 가시 갑옷으로 이어가 상처를 걸어 두세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'피의 갈망\' 회복을 눌러 트린다미어를 끊을 각을 만드세요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'로 평타마다 독을 쌓고 (Q)\'실명 다트\'로 대상을 실명시켜 근접 챔피언을 괴롭혀요. 실명에 걸리면 평타가 빗나가니 그 동안은 (Q)\'대량 학살 강타\'나 (E)\'학살자의 포효\' 같은 스킬 교환으로 압박하세요. 티모가 수풀에 서 있으면 (P)\'유격 전투\'로 투명해지니 웨이브를 수풀 반대쪽에 두세요.', lv3: '(W)\'신속한 이동\'으로 이동 속도를 올려 도망가는 티모는 쫓기 어렵지만 공격받으면 효과가 끊기니 피해를 한 번 맞히면 속도가 줄어요. 티모가 Q를 빼면 (W)\'영혼의 용광로\' 보호막을 켜고 붙어서 짧게 교환하세요. 티모가 수풀에서 투명해지면 무리하게 쫓지 마세요.', lv6: '(R)\'유독성 함정\'은 버섯을 밟으면 독 구름이 퍼져 둔화와 피해를 주니 라인과 수풀 길목에 깔린 버섯을 피해 다니세요. 버섯 위에 새 버섯을 던지면 더 멀리까지 깔리니 시야가 없는 수풀로 뛰어들지 마세요. 티모가 투명해지기 전에 (R)\'멈출 수 없는 맹공\'으로 띄워 끊는 편이 좋아요.', item: '티모는 독과 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 신발은 버섯 독 구름의 둔화를 줄여 주는 신속의 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 티모가 라인을 비워 견제하는 구도라 순간이동으로 귀환 후 복귀하세요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 찌르거나 던져 견제하고 (P)\'필멸자의 의지\'로 몇 번의 공격 뒤 다음 스킬이 강화되는 근접 교환형이에요. 판테온이 창을 던지는 직선에서 비켜서고, 강화된 스킬이 준비된 순간에는 교환을 피하세요. 판테온의 초반 화력이 강하니 막타를 챙기며 짧게 교환하세요.', lv3: '(W)\'방호의 도약\'은 대상에게 돌진해 피해와 기절을 주니 판테온의 W가 남아 있을 때는 붙지 마세요. (E)\'방패 돌격\'은 정면의 공격으로부터 무적이 되니 판테온이 방패를 든 동안은 정면으로 (Q)\'대량 학살 강타\'를 쓰지 말고 아끼세요. 판테온이 W를 뺀 직후에 (W)\'영혼의 용광로\' 보호막을 켜고 교환하세요.', lv6: '(R)\'거대 유성\'은 판테온이 공중으로 뛰어올랐다가 지정한 위치에 떨어지니 유성이 떨어질 위치를 보고 범위 밖으로 비켜서세요. 판테온이 (R)\'거대 유성\'으로 다른 라인에 합류하면 그동안 웨이브를 밀어 포탑을 압박하세요. (W)\'방호의 도약\'이 빠진 판테온에게 (R)\'멈출 수 없는 맹공\'으로 달려들어 띄워 끝내세요.', item: '판테온은 물리 피해 중심이라 태양불꽃 방패로 방어력과 체력을 챙기세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 판테온의 초반 화력에 대응하려면 점화로 마무리 피해를 확보하세요.' },
    '피들스틱': { lv1: '피들스틱이 시야 밖에서 (Q)\'공포\'를 사용하여 공포를 거는 것을 경계하며 미니언을 받아먹어요. (W)\'영혼의 용광로\'를 사용해 적의 마법 피해를 흡수하며 체력을 관리하세요. 초반에는 무리하게 싸우기보다 거리를 유지하며 안정적으로 성장하는 것이 좋아요.', lv3: '상대의 (W)\'풍작\' 사용을 유도해 체력 회복 수단을 먼저 빼내는 것이 중요해요. (E)\'학살자의 포효\'를 맞춰 둔화시킨 뒤 (Q)\'대량 학살 강타\'를 충전해 적을 공중으로 띄워보세요. (E)\'수확\'에 의해 침묵이 걸리기 전에 내 스킬을 먼저 적중시켜야 해요.', lv6: '(R)\'까마귀 폭풍\'은 정신 집중 후 대상 지역으로 순간 이동하는 스킬이라 갑자기 진입해 올 수 있으니 라인을 너무 밀어 두지 마세요. 피들스틱이 까마귀 범위로 들어오면 (R)\'멈출 수 없는 맹공\'으로 돌진해 부딪혀 기절시키고 싸움을 시작하세요. 이후에는 (Q)\'대량 학살 강타\'를 충전해 마무리하세요.', item: '헤르메스의 발걸음과 강철심장을 가요. 피들스틱의 마법 피해를 견디기 위해 헤르메스의 발걸음을 사고, 체력을 쌓기 위해 강철심장을 선택해요.', spell: '점멸과 정화를 추천해요. 정화는 (Q)\'공포\'의 공포와 (E)\'수확\'의 침묵과 둔화를 풀 수 있어요.' },
    '피오라': { lv1: '피오라는 (Q)\'찌르기\'로 돌진해 급소를 가격하면 (P)\'치명적인 검무\'로 체력을 회복하고 이동 속도를 올리는 근접 결투형이에요. 피오라가 Q로 돌진해 오는 방향을 읽고, 내 급소가 드러난 쪽을 피오라에게 내주지 않도록 위치를 바꾸세요. 피오라의 (E)\'대가의 검술\'로 평타 속도가 올라가는 순간에는 교환을 피하세요.', lv3: '(W)\'응수\'는 잠시 모든 공격과 이동 불가 효과를 막고, 이동 불가 효과를 막아내면 찌르기로 공격한 상대를 기절시키니 피오라가 W를 켠 동안 충전을 마친 (Q)\'대량 학살 강타\'를 쓰면 오히려 내가 기절할 수 있어요. 피오라의 W가 빠진 뒤에 기절을 맞혀야 안전해요. 피오라가 W 자세를 취하는 모습이 보이면 (W)\'영혼의 용광로\' 보호막을 켜 두세요.', lv6: '(R)\'대결투\'는 적 챔피언의 급소 네 군데를 모두 드러내고 근처에서 피오라의 이동 속도를 올리니 궁극기에 걸리면 피오라와 일대일이 되는 구도라는 점을 기억하세요. (W)\'응수\'가 빠진 것을 확인한 뒤 (R)\'멈출 수 없는 맹공\'으로 붙어 띄워 피오라가 궁극기를 쓰기 전에 체력을 깎아 두세요. 체력이 낮은 피오라는 회복으로 되돌아오니 정글러와 함께 마무리하세요.', item: '피오라는 물리 피해가 중심이라 태양불꽃 방패로 방어력과 체력을 챙기고, 평타 교환이 많아지면 가시 갑옷으로 이어가 상처를 걸어 두세요. 신발은 평타 피해를 줄이는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 피오라의 회복을 눌러야 일대일 결투에서 이득을 굳힐 수 있어요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'으로 속사포 포탑을 설치해 압박하고 (W)\'마법공학 초소형 로켓\'으로 견제하는 원거리 챔피언이에요. 포탑 사거리 안에서 서성이지 말고 (E)\'학살자의 포효\'로 미니언을 밀어 포탑 뒤의 하이머딩거에게 방어력 감소를 노려 보세요. 하이머딩거는 포탑 주변에서 이동 속도가 올라가니 포탑이 설치된 곳에서는 쫓지 마세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'은 직격당하면 기절하고 빗겨 맞으면 느려지니 수류탄이 떨어지는 지점을 보고 비켜서세요. 수류탄이 빠진 하이머딩거는 로켓 말고 막을 수단이 적으니 그때 붙어 (Q)\'대량 학살 강타\'를 충전하세요. 로켓은 마우스 위치로 모이니 직선 방향을 읽고 옆으로 움직이세요.', lv6: '(R)\'업그레이드!!!\'는 다음 스킬 하나를 강화하니 하이머딩거가 궁극기를 켠 직후에는 수류탄이나 로켓이 평소보다 강하게 온다고 보고 (W)\'영혼의 용광로\' 보호막을 미리 켜세요. 강화된 스킬이 빠진 하이머딩거에게는 (R)\'멈출 수 없는 맹공\'으로 달려들어 띄우세요. 포탑과 수류탄을 한꺼번에 받는 구간에서는 한 번에 끝낼 각이 아니면 붙지 마세요.', item: '하이머딩거는 마법 피해 중심이라 공허한 광휘로 마법 저항력과 체력을 챙기세요. 수류탄 직격 기절이 위험하니 신발은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 하이머딩거가 포탑으로 압박하는 라인이라 순간이동으로 귀환 후 복귀하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_sion);
if (typeof module !== 'undefined') module.exports = top_sion;
